  FT["PH-H926"] = {"id":"PH-H926","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1091_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"通过进一步修订第588号共和国法第8条，延长该法（即《修订第466号联邦法，即《国家国内税收法典》，若干条文》，经修正）效力的法案","en":"An Act to Extend the Effectivity of Republic Act Numbered Five Hundred and Eighty-Eight, by Further Amending Section Eight Thereof, Entitled “An Act to Amend Certain Sections of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code,” as Amended","orig":"An Act to Extend the Effectivity of Republic Act Numbered Five Hundred and Eighty-Eight, by Further Amending Section Eight Thereof, Entitled “An Act to Amend Certain Sections of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code,” as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1091","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1091_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H926-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eight of Republic Act Numbered Five hundred and eighty-eight, as amended by Republic Act Numbered Seven hundred and twenty-six and Republic Act Numbered Nine hundred and fifty-eight, is further amended to read as follows:\n\"Sec. 8. This Act shall take effect upon its approval, but, unless otherwise expressly extended by Congress, the increased taxes provided for in this Act shall continue in force and effect only until December thirty-one, nineteen hundred and fifty-five, after which period the original rates of tax shall again be in force.\""}},{"id":"PH-H926-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Extend the Effectivity of Republic Act Numbered Five Hundred and Eighty-Eight, by Further Amending Section Eight Thereof, Entitled “An Act to Amend Certain Sections of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code,” as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H927"] = {"id":"PH-H927","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1092_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"通过进一步修订第567号共和国法第7条，延长该法（即《修订第466号联邦法第六编，即《国家国内税收法典》，经修正》）效力的法案","en":"An Act to Extend the Effectivity of Republic Act Numbered Five Hundred and Sixty-Seven, by Further Amending Section Seven Thereof, Entitled “An Act to Amend Title Six of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended”","orig":"An Act to Extend the Effectivity of Republic Act Numbered Five Hundred and Sixty-Seven, by Further Amending Section Seven Thereof, Entitled “An Act to Amend Title Six of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended”"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1092","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1092_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H927-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section seven of Republic Act Numbered Five hundred and sixty-seven, as amended by Republic Act Numbered Seven hundred and twenty-five, and Republic Act numbered Eight hundred and seventy, is further amended to read as follows:\n\"Sec. 7. This Act shall take effect upon its approval, but unless otherwise expressly extended by Congress, the increased taxes provided for in this Act shall continue in force and effect until December thirty-one, nineteen hundred and fifty-five.\""}},{"id":"PH-H927-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Extend the Effectivity of Republic Act Numbered Five Hundred and Sixty-Seven, by Further Amending Section Seven Thereof, Entitled “An Act to Amend Title Six of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H928"] = {"id":"PH-H928","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1093_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"对逃税及故意拒缴税款的外侨以驱逐出境处罚的法案","en":"An Act to Punish Tax Evasion and Wilful Refusal to Pay Taxes by Aliens with Deportation","orig":"An Act to Punish Tax Evasion and Wilful Refusal to Pay Taxes by Aliens with Deportation"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1093","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1093_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H928-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any alien who shall knowingly and fraudulently evade the payment of any internal revenue tax or wilfully refuses to pay such tax and the accessory penalties thereof after the decision on his liability, rendered by the Collector of Internal Revenue or the Board of Tax Appeals or any competent administrative agency or judicial tribunal, now existing or which may hereafter be created by law, shall have become final and executory, shall be liable to deportation. If such tax evasion or wilful refusal to pay is committed by a corporation, association, or partnership, the officers thereof, who are aliens who directly participate in the commission of the fraudulent tax evasion or who wilfully refuse the collection of such tax after liability therefor has become final and executory, shall be liable to deportation. The imposition of the penalty of deportation herein provided shall not be a bar to any proceeding, administrative or judicial, which may be taken by the Government to enforce the collection of the tax delinquency."}},{"id":"PH-H928-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Collector of Internal Revenue shall submit on or before January thirty-one every year to the Solicitor General and to the Deportation Board a list of tax cases involving aliens with a statement regarding their status. He shall also submit to the Solicitor General and to the Deportation Board a copy of the final decisions rendered in such cases, whether by compromise or otherwise, within fifteen days after they become final. The documents herein required to be submitted by the Collector of Internal Revenue shall be open to public inspection."}},{"id":"PH-H928-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Punish Tax Evasion and Wilful Refusal to Pay Taxes by Aliens with Deportation","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H929"] = {"id":"PH-H929","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1094_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对《国家国内税收法典》的修改","en":"An Act to Amend Section Twenty-One of Commonwealth Act Numbered Four Hundred Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended","orig":"An Act to Amend Section Twenty-One of Commonwealth Act Numbered Four Hundred Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1094","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1094_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H929-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty-one of the National Internal Revenue Code, as amended, is further amended to read as follows:\n\"Sec. 21. Rates of tax on citizens or residents. -There shall be levied, assessed, collected, and paid annually upon the entire net income received by the preceding taxable year from all sources by every individual, a citizen or resident of the Philippines, a tax equal to the sum of the following:\n\"Five per centum per annum upon the amount by which such total net income does not exceed two thousand pesos;\n\"Eight per centum per annum upon the amount by which such total net income exceed two thousand pesos and does not exceed four thousand pesos;\n\"Twelve per centum per annum upon the amount by which such total net income exceeds two thousand pesos;\n\"Sixteen per centum per annum upon the amount by which such total net income exceed six thousand pesos and does not exceed eight thousand pesos;\n\"Twenty per centum per annum upon the amount by which such total net income exceeds eight thousand pesos and does not exceed ten thousand pesos;\n\"Twenty-four per centum per annum upon the amount by which such total net income exceeds ten thousand pesos; and does not exceed twenty thousand pesos;\n\"Thirty per centum per annum upon the amount by which such total net income exceeds twenty thousand pesos and does not exceed thirty thousand pesos;\n\"Thirty-six per centum per annum upon the amount by which such total net income exceeds thirty thousand pesos and does not exceed forty thousand pesos;\n\"Forty per centum per annum upon the amount by which such total net income exceeds forty thousand pesos and does not exceed fifty thousand pesos;\n\"Forty-two per centum per annum upon the amount by which such total net income exceeds fifty thousand pesos and does not exceed sixty thousand pesos;\n\"Forty-four per centum per annum upon the amount by which such total net income exceeds sixty thousand pesos and does not exceed seventy thousand pesos;\n\"Forty-six per centum per annum upon the amount by which such total net income exceeds seventy thousand pesos and does not exceed eighty thousand pesos;\n\"Forty-eight per centum per annum upon the amount by which such total net income exceeds eighty thousand pesos and does not exceed ninety thousand pesos;\n\"Fifty per centum per annum upon the amount by which such total net income exceeds ninety thousand pesos and does not exceed one hundred thousand pesos;\n\"Fifty-two per centum per annum upon the amount by which such total net income exceeds one hundred thousand pesos and does not exceed one hundred and twenty thousand pesos;\n\"Fifty-three per centum per annum upon the amount by which such total net income exceeds one hundred and twenty thousand pesos and does not exceed one hundred and forty thousand pesos;\n\"Fifty-four per centum per annum upon the amount by which such total net income exceeds one hundred and forty thousand pesos and does not exceed one hundred and sixty thousand pesos;\n\"Fifty-five per centum per annum upon the amount by which such total net income exceeds one hundred and sixty thousand pesos and does not exceed one two hundred thousand pesos;\n\"Fifty-six per centum per annum upon the amount by which such total net income exceeds two hundred thousand pesos and does not exceed one two hundred and fifty thousand pesos;\n\"Fifty-seven per centum per annum upon the amount by which such total net income exceeds two hundred and fifty thousand pesos and does not exceed three hundred thousand pesos;\n\"Fifty-nine per centum per annum upon the amount by which such total net income exceeds three hundred thousand pesos and does not exceed four hundred thousand pesos;\n\"Sixty per centum per annum upon the amount by which such total net income exceeds five hundred thousand pesos.\""}},{"id":"PH-H929-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval; Provided, However , That the rates of hereinabove fixed shall apply to income to received from January first, nineteen hundred and fifty-four, to December thirty-first, nineteen hundred and fifty-five.\nApproved: June 15, 1954."}}],"pack":"ph-p13"};
  FT["PH-H930"] = {"id":"PH-H930","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1095_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订经修正的《修正行政法典》第2071条的法案","en":"An Act to Amend Section Two Thousand and Seventy-One of the Revised Administrative Code, as Amended","orig":"An Act to Amend Section Two Thousand and Seventy-One of the Revised Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1095","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1095_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H930-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two thousand and seventy-one of the Revised Administrative Code, as amended by section one of Commonwealth Act Numbered Two hundred and thirty-three, is hereby further amended to read as follows:\n\"Sec. 2071. Qualifications of provincial officer. -No person shall be eligible to a provincial office unless at the time of the election he is a qualified voter of the province, has been a bona fide resident therein for at least one year prior to the election, and is not less than twenty-five years of age.\""}},{"id":"PH-H930-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Two Thousand and Seventy-One of the Revised Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H931"] = {"id":"PH-H931","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1096_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"进一步修订第496号法（即“土地登记法”）第58条，便于在小区测量批准前处理政府售出土地的交易","en":"An Act Further Amending Section Fifty-Eight of Act Numbered Four Hundred Ninety-Six, Known as the “Land Registration Act,” to Facilitate Dealings in Lands Sold by the Government Pending Approval of the Subdivision Surveys","orig":"An Act Further Amending Section Fifty-Eight of Act Numbered Four Hundred Ninety-Six, Known as the “Land Registration Act,” to Facilitate Dealings in Lands Sold by the Government Pending Approval of the Subdivision Surveys"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1096","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1096_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H931-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section fifty-eight of Act Numbered Four hundred ninety-six, known as the Land Registration Act, is hereby further amended by adding at the end thereof the following additional paragraph:\n\"For the purpose of securing loans from banking and credit institutions, the foregoing prohibition against the acceptance for registration or annotation of a subsequent deed or other voluntary instrument shall not apply in the case of deeds of sale duly executed by the Government or any of its instrumentalities, with respect to portions of lands registered in the name of the Republic of the Philippines.\""}},{"id":"PH-H931-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All laws and regulations, or parts thereof inconsistent with the provisions of this Act, are hereby repealed."}},{"id":"PH-H931-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval Approved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amending Section Fifty-Eight of Act Numbered Four Hundred Ninety-Six, Known as the “Land Registration Act,” to Facilitate Dealings in Lands Sold by the Government Pending Approval of the Subdivision Surveys","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H932"] = {"id":"PH-H932","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1097_1954.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"修订第 720 号共和国法（即《乡村银行法》）若干条的法案","en":"An Act to Amend Certain Sections of Republic Act Numbered Seven Hundred Twenty, Otherwise Known as the Rural Banks Act","orig":"An Act to Amend Certain Sections of Republic Act Numbered Seven Hundred Twenty, Otherwise Known as the Rural Banks Act"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1097","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1097_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H932-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section four of Republic Act Numbered Seven hundred twenty, otherwise known as the Rural Banks Act, is hereby amended to read as follows:\n\"Sec. 4. No Rural Bank shall be operated without a Certificate of Authority of the Monetary Board of the Central Bank. Rural Banks shall be organized in the form of stock corporations. Duly established cooperatives may organize Rural Banks and/or subscribed to the shares of stock of any Rural Bank. At least sixty per cent of the capital stock of any Rural Bank shall be owned and held by citizens of the Philippines: Provided, However , That if said subscription of private shareholders to the capital stock of Rural Bank cannot be secured or is not available, the Rehabilitation Finance Corporation, on representation of the said private shareholders and upon approval of the Monetary Board of the Central Bank, shall subscribe to the capital stock of such rural bank, which shall be paid in full at the time of subscription, in an amount equal to the fully paid subscribed capital of the private shareholders: Provided, further, That such shares of stock subscribed by the Rehabilitation Finance Corporation may be sold at any time at par to private individuals who are citizens of the Philippines: Provided, finally, That in the sale of the shares of stock registered by the Rehabilitation Finance Corporation, the registered stockholders shall have the right or preemption within five years from the date of offer in proportion to their respective holdings, but in the absence of such buyer, preference, however, shall be given to residents of the locality of province where the Rural Bank is located. All members of the Board of Directors of the Rural Banks shall be citizens of the Philippines.\""}},{"id":"PH-H932-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section seven of the same Act is amended to read as follows:\n\"Sec. 7. To provide supplemental capital to any Rural Bank until it has accumulated enough capital of its own or stimulate private investments in Rural Banks, the Rehabilitation Finance Corporation shall, upon certification of the Monetary Board which shall be final, of the existence of such need, subscribe within thirty days to capital stock of any Rural Bank from time to time in an amount equal to but not exceeding the total equity investment of the private shareholders: Provided, However , That shares of stock issued to the Rehabilitation Finance Corporation, pursuant to this section, may at any time be paid off at par and retired in whole or in part if, in the opinion of the Monetary Board, the Rural Banks has accumulated enough capital strength to permit retirement of such shares; or if an offer is received from private sources, to replace the equity investments of the Rehabilitation Finance Corporation with an equivalent investment or more in the common stock or replacement of equity investments of the Rehabilitation Finance Corporation, the registered private shareholders of the Rural Bank shall have the right of preemption within five years from date of offer in proportion to their respective holdings.\n\"Stock held by the Rehabilitation Finance Corporation, under the terms of this section, shall be made preferred only as to assets upon liquidation and without the power to vote and shall share in dividend distributions not exceeding two percent thereof without preference; Provided, However, That if such stock of the Rehabilitation Finance Corporation is sold to private shareholders, the same shall be converted into common stock of the class provided for in section nine.\""}},{"id":"PH-H932-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section twelve of the same Act is amended to read as follows:\n\"Sec. 12. The Rehabilitation Finance Corporation shall, within sixty days of certification of the Monetary Board, which shall be final, extend to a Rural Bank a loan or loans from time to time repayable in ten years, with interest at the rate of two per cent per annum, against security which may be offered by any stockholder or stockholders of the Rural Bank: Provided — \"(a) That the Monetary Board is convinced that the resources of the Rural Bank are inadequate to meet the legitimate credit requirements of the locality wherein the Rural Bank is established;\n\"(b) That there is a dearth of private capital in the said locality; and \"(c) That is not possible for the stockholders of the Rural Bank to increase the paid-up capital thereof.\""}},{"id":"PH-H932-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section fourteen of the same Act is amended to read as follows:\n\"Sec. 14. All Rural Banks created and organized under the provisions of this Act, with net assets not exceeding seven hundred thousand pesos, shall be exempt from the payment of all taxes, charges and fees of whatever nature and description.\""}},{"id":"PH-H932-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section sixteen of the same Act is amended to read as follows:\n\"Sec. 16. Any justice of the peace, in his capacity as notary ex-officio, shall administer the oath to or acknowledge the instruments of any Rural Bank and its borrowers or mortgagors, free from all charges, fees and documentary stamp tax, collectible under the existing laws, relative to any loan or transaction not exceeding two thousand pesos.\""}},{"id":"PH-H932-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section seventeen of the same Act is amended to read as follows:\n\"Sec. 17. Any register of deeds shall accept from any Rural Bank and its borrowers or mortgagors for registration, free from all charges, fees, and documentary stamp tax, collectible under existing laws, any instrument, whether voluntary or involuntary, relating to loans or transactions extended by a Rural Bank in an amount not exceeding two thousand pesos; Provided, However , That charges if any shall only be collectible on the amount in excess of two thousand pesos; and that in instruments related to assignments of several mortgages consolidated in a single deed, charges or fees, if any, shall be levied only on the amount in excess of two thousand pesos of the consideration in the assignment of each mortgage.\""}},{"id":"PH-H932-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section twenty-three of the same Act is amended to read as follows:\n\"Sec. 23. Any justice of the peace or register of deeds who shall demand or accept, directly or indirectly, any gift, fee, commission or other form of compensation in connection with the service or shall arbitrarily or without reasonable cause delay the acknowledgment or administration of oath or the registration of documents required to be performed by said justice of the peace as provided in section sixteen and by said register of deeds as provided in section seventeen of this Act, shall be punished by a fine of not more than one thousand pesos or by imprisonment for not more than one year, or both, at the discretion of the court.\""}},{"id":"PH-H932-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section twenty five of the same Act is amended to read as follows:\n\"Sec. 25. The Monetary Board of the Central Bank shall submit a report to the Congress as of the end of each calendar year of all the rules and regulations promulgated by it in accordance with the provisions of this Act, as well as its other actuations in connection with Rural Banks, together with an explanation of its reasons therefor.\""}},{"id":"PH-H932-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of Republic Act Numbered Seven Hundred Twenty, Otherwise Known as the Rural Banks Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H933"] = {"id":"PH-H933","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1098_1954.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of One Million Pesos as Working Capital of the Prison Industries and Salvage Warehouse Revolving Fund, and Providing for its Annual Amortization Within the Period of Ten Years","orig":"An Act Appropriating the Sum of One Million Pesos as Working Capital of the Prison Industries and Salvage Warehouse Revolving Fund, and Providing for its Annual Amortization Within the Period of Ten Years"},"level":"law","status":"active","topics":["trade"],"docNumber":"Republic Act No. 1098","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1098_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H933-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of one million pesos is hereby appropriated out of any funds in the National Treasury not otherwise appropriated as working capital of the Prison Industries and Salvage Warehouse Revolving Fund. Any cash overdraft of the said Revolving Fund which may be found existing and certified to as correct by the Auditor General upon approval of this Act, shall be considered as advanced from the general fund."}},{"id":"PH-H933-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The working capital herein provided for may be released by the Auditor General to the Bureau of Prisons in one lump sum upon certification of the Commissioner of the Budget as to the necessity thereof."}},{"id":"PH-H933-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The working capital herein appropriated as well as the cash overdraft shall be repaid to the National Treasury by the Prison Industries and Salvage Warehouse Revolving fund during a period of ten years beginning with the fiscal year 1955-1956 on the annual amortization basis."}},{"id":"PH-H933-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13"};
  FT["PH-H934"] = {"id":"PH-H934","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1099_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权朗布隆省朗布隆市镇填拓其临Romblon湾的部分滩涂，并将相关产权授予该市镇的法案","en":"An Act Authorizing the Municipality of Romblon in the Province of Romblon to Reclaim a Portion of its Foreshore Bordering Romblon Bay and Vesting Title Thereto in the Said Municipality","orig":"An Act Authorizing the Municipality of Romblon in the Province of Romblon to Reclaim a Portion of its Foreshore Bordering Romblon Bay and Vesting Title Thereto in the Said Municipality"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1099","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1099_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H934-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The municipality of Romblon in the Province of Romblon is hereby authorized to reclaim a portion not exceeding five hectares of its foreshore bordering Romblon Bay. After reclamation, title to the area reclaimed shall vest in the said municipality and, thereafter, the said municipality shall subdivide said reclaimed area into lots or blocks of suitable size for the purpose of constructing public improvements thereon, and the lots or blocks not needed for public purposes may be leased by it for commercial or industrial purposes or for the purpose of providing homesites for its inhabitants: Provided, That the new foreshore along the reclaimed lands shall continue to be property of the National Government."}},{"id":"PH-H934-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Municipality of Romblon in the Province of Romblon to Reclaim a Portion of its Foreshore Bordering Romblon Bay and Vesting Title Thereto in the Said Municipality","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H935"] = {"id":"PH-H935","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1100_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将马林杜克省莫格波格市镇希南加永小村改设为希南加永村的法案","en":"An Act to Convert the Sitio of Hinangayon, Mogpog, Marinduque, into a Barrio to be Known as the Barrio of Hinangayon","orig":"An Act to Convert the Sitio of Hinangayon, Mogpog, Marinduque, into a Barrio to be Known as the Barrio of Hinangayon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1100","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1100_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H935-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Hinangayon, barrio of Argao, municipality of Mogpog, Province of Marinduque, is hereby converted into a barrio to be known as the barrio of Hinangayon."}},{"id":"PH-H935-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Convert the Sitio of Hinangayon, Mogpog, Marinduque, into a Barrio to be Known as the Barrio of Hinangayon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H936"] = {"id":"PH-H936","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1101_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第920号共和国法第1条 F编第II组第136项的法案","en":"An Act to Amend Item One Hundred and Thirty-Six, Group II, Title F of Section One of Republic Act Numbered Nine Hundred Twenty","orig":"An Act to Amend Item One Hundred and Thirty-Six, Group II, Title F of Section One of Republic Act Numbered Nine Hundred Twenty"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1101","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1101_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H936-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item one hundred and thirty-six, group II, title F of Section One of Republic Act Numbered Nine hundred twenty is hereby amended to read as follows:\n\"136. Siaton River Control, Siaton, Negros Oriental 40,000.00\""}},{"id":"PH-H936-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Item One Hundred and Thirty-Six, Group II, Title F of Section One of Republic Act Numbered Nine Hundred Twenty","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H937"] = {"id":"PH-H937","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1102_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"明确划定达沃省Tagum市镇与Doña Alicia及Compostela市镇之间的行政边界线的法案","en":"An Act Fixing the Boundary Line Between the Municipality of Tagum and the Municipalities of Doña Alicia and Compostela, Province of Davao","orig":"An Act Fixing the Boundary Line Between the Municipality of Tagum and the Municipalities of Doña Alicia and Compostela, Province of Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1102","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1102_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H937-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The boundary line between the municipality of Tagum and Doña Alicia shall be the Dumlan River from the Gulf of Davao to the source of said river and a straight line from said source running northwestward to the concrete monument in the sitio of Libaybay. The boundary line between the municipalities of Tagum and Compostela shall be the Hijo River."}},{"id":"PH-H937-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Executive Order No. 596, series of 1953, is amended accordingly."}},{"id":"PH-H937-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Fixing the Boundary Line Between the Municipality of Tagum and the Municipalities of Doña Alicia and Compostela, Province of Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H938"] = {"id":"PH-H938","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1103_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将东明多洛省纳万市镇圣奥古斯丁小学的名称变更为Santiago Garong纪念学校的法案","en":"An Act Changing the Name of the San Agustin Elementary School in the Municipality of Naujan, Province of Oriental Mindoro, to Santiago Garong Memorial School","orig":"An Act Changing the Name of the San Agustin Elementary School in the Municipality of Naujan, Province of Oriental Mindoro, to Santiago Garong Memorial School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1103","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1103_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H938-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the San Agustin Elementary School in the municipality of Naujan, Province of Oriental Mindoro, is changed to Santiago Garong Memorial School."}},{"id":"PH-H938-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the San Agustin Elementary School in the Municipality of Naujan, Province of Oriental Mindoro, to Santiago Garong Memorial School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
