  FT["PH-H940"] = {"id":"PH-H940","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1105_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将东明多洛省 Baco市镇 Baco 小学的名称变更为Benito Villar 纪念学校的法案","en":"An Act Changing the Name of the Baco Elementary School in the Municipality of Baco, Province of Oriental Mindoro, to Benito Villar Memorial School","orig":"An Act Changing the Name of the Baco Elementary School in the Municipality of Baco, Province of Oriental Mindoro, to Benito Villar Memorial School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1105","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1105_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H940-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Baco Elementary School in the Municipality of Baco, Province of Oriental Mindoro, is changed to Benito Villar Memorial School."}},{"id":"PH-H940-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Baco Elementary School in the Municipality of Baco, Province of Oriental Mindoro, to Benito Villar Memorial School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
