  FT["PH-H951"] = {"id":"PH-H951","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1116_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将马斯巴特省Limbuhan市镇的名称正式变更为Pio V. Corpus的法案","en":"An Act Changing the Name of the Municipality of Limbuhan, Province of Masbate to Pio V. Corpus","orig":"An Act Changing the Name of the Municipality of Limbuhan, Province of Masbate to Pio V. Corpus"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1116","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1116_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H951-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In recognition of the eminent and patriotic services rendered by the late Pio V. Corpus, the name of the municipality of Limbuhan, Province of Masbate, is changed to Pio V. Corpus."}},{"id":"PH-H951-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Municipality of Limbuhan, Province of Masbate to Pio V. Corpus","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H952"] = {"id":"PH-H952","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1117_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Odiongan市","en":"An Act Creating the Barrio of Budiong, Municipality of Odiongan, Province of Romblon","orig":"An Act Creating the Barrio of Budiong, Municipality of Odiongan, Province of Romblon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1117","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1117_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H952-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Budiong of barrio Canduyong, municipality of Odiongan, Province of Romblon, is separated from said barrio and constituted into a new barrio to be known as barrio Budiong. The new barrio shall comprise that territory bounded on the North by the Odiongan Bay; on the East by the Bangon River; on the South by the National Road to Ferrol; and on the West by the Budiong Hill starting from the Siniba-an Point on Odiongan Bay extending the National Road to Ferrol following the ridge of the said hill."}},{"id":"PH-H952-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13"};
  FT["PH-H953"] = {"id":"PH-H953","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1118_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"何塞·卡托利科电灯与动力公司","en":"Jose Catolico Electric Light and Power Co., Inc.","orig":"An Act Approving Any Assignment, Sale and Transfer of the Franchise Granted to Jose Catolico by Republic Act Numbered Four Hundred and Sixty-Six in Favor of “Jose Catolico Electric Light and Power Co., Inc.”"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1118","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1118_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H953-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of Republic Act Numbered Four hundred and sixty-six, entitled \"An Act granting Jose Catolico a franchise for an electric light, heat and power system in the municipality of Buayan, Province of Cotabato,\" approval is hereby given to any assignment, sale and transfer of the franchise granted to Jose Catolico under the said Act, together with all the property and equipment acquired thereunder, in favor of \"Jose Catolico Electric Light and Power Plant Co., Inc.\""}},{"id":"PH-H953-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Jose Catolico Electric Light and Power Co., Inc.","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H954"] = {"id":"PH-H954","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1119_1954.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Martha Enterprises, Inc. 设立、维护和运营私人固定点对点无线电话站的临时许可的法案","en":"An Act Granting the Martha Enterprises, Inc. Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission and Reception of Wireless Messages to and from Said Stations","orig":"An Act Granting the Martha Enterprises, Inc. Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission and Reception of Wireless Messages to and from Said Stations"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1119","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1119_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H954-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Martha Enterprises, Inc. its successors or assigns is hereby granted a temporary permit to establish, maintain and operate private fixed point-to-point radiotelephone stations in the City of Zamboanga and in other parts of the Philippines where it operates its lumber business, subject to the approval of the Secretary of Public Works and Communications, for the transmission and reception of wireless messages to and from said stations, including its tugboats."}},{"id":"PH-H954-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction, maintenance, and operation of said private fixed point-to-point radiotelephone stations on any land of the public domain upon such terms as he may prescribe."}},{"id":"PH-H954-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The temporary permit granted under this Act shall continue to be in force while the Government has not established similar service at places hereinabove stated, and subject to the condition that the grantee, its successors or assigns, shall start operation under said temporary permit within one and a half years from the approval of this Act."}},{"id":"PH-H954-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines, it being understood that the temporary permit granted by virtue of this Act merely secures the right of the grantee to establish, maintain and operate private fixed point-to-point radiotelephone stations at the places hereinabove stated for no other purpose than to promote, protect, and subserve the trade and business interest of the grantee as a lumber company."}},{"id":"PH-H954-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The actual operation of said private fixed point-to-point radiotelephone operation shall not commence until after the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder."}},{"id":"PH-H954-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate such stations as not interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H954-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial, city and municipal government of the Republic of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radiotelephone stations."}},{"id":"PH-H954-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted."}},{"id":"PH-H954-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, rebellion, public peril, company, disaster or disturbance of peace or order to cause the closing of the grantee’s radiotelephone stations or to authorize the temporary use and operation thereof by any department of the Government upon just compensation."}},{"id":"PH-H954-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The temporary permit granted under this Act shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H954-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Martha Enterprises, Inc. Temporary Permit to Establish, Maintain and Operate Private Fixed Point-to-Point Radiotelephone Stations for the Transmission and Reception of Wireless Messages to and from Said Stations","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H955"] = {"id":"PH-H955","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1120_1954.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Philippine Packing Corporation 在菲律宾境内建设、维护和运营私人固定点对点、基站与海岸无线电台的临时许可的法案","en":"An Act Granting to Philippine Packing Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Private Base, and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting to Philippine Packing Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Private Base, and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1120","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1120_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H955-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Philippine Packing Corporation, its successors or assigns, a temporary permit to construct, establish, maintain and operate in the Philippines, at Manila, Bugo and Phillips, Bukidnon, and at such other places as the company may select and the Secretary of Public Works and Communications may approve, private fixed point-to-point, private base, and private coastal radio stations for the reception and transmission of wireless messages on radio radiotelegraphy or radiotelephony, each station to be provided with a radio transmission apparatus and a radio receiving apparatus."}},{"id":"PH-H955-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point, private base, and private coastal radio stations, or any of them, on lands of the public domain upon such terms as he may prescribe."}},{"id":"PH-H955-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during that the time the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the construction of at least two stations be begun within two years from the date of approval of this Act, and all of them be completed within six years from said date."}},{"id":"PH-H955-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, maintain and operate private fixed point-to-point, private base, and private coastal radio stations in such places within the Philippines as the interest of the company and of its trade and business may justify."}},{"id":"PH-H955-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wage lengths to be used by the stations."}},{"id":"PH-H955-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees shall be charged by the grantee, as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H955-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operated its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H955-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H955-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H955-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the grantee’s radio station or to authorize the temporary use of possession thereof by any department of the Government upon just compensation."}},{"id":"PH-H955-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of privilege herein provided for."}},{"id":"PH-H955-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting to Philippine Packing Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point, Private Base, and Private Coastal Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H956"] = {"id":"PH-H956","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1121_1954.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Philippine Standard Products 公司在马尼拉建设、维护和运营无线电广播站的特许经营权法案","en":"An Act Granting the Philippine Standard Products Co,. Inc. a Franchise to Construct, Maintain and Operate a Radio Broadcasting Station in Manila, Philippines","orig":"An Act Granting the Philippine Standard Products Co,. Inc. a Franchise to Construct, Maintain and Operate a Radio Broadcasting Station in Manila, Philippines"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 1121","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1121_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H956-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitutions, as well as of Act Numbered Three Thousand eight hundred forty-six, entitled An Act providing for the regulation of radio stations and radio communications in the Philippines Islands, and for other purposes; Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, there is hereby granted to the Philippine Standard Products Co., Inc., hereinafter referred to as the \"grantee\" a franchise to construct, maintain and operate in Manila, Philippines and in such other places as may be selected by the grantee, subject to the approval of the Secretary of Public Works and Communications, a radio broadcasting station or stations; Provided, that the holder of the franchise herein granted shall start the operation thereof within two years from the approval of said franchise. Failure to comply with this requirement shall ipso facto cancel and void the franchise."}},{"id":"PH-H956-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years, renewable upon expiration."}},{"id":"PH-H956-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"(a) This franchise shall not take effect nor shall any powers thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder and determined the stations to and from which each such frequency and wave length may be used, and issued to the grantee a license for such use.\n(b) The Secretary of Public Works and Communications, on reasonable notice to the grantee, may at any time change, or cancel, or modify, in whole or in part, any or all of the allotments of frequencies or wave lengths to be used. He may take such action: (1) whenever in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communications, or stifle competition, or to obtain a monopoly in electrical communications, or to secure unreasonable rates for such communication, or otherwise to violate the laws or public policy of the Republic of the Philippines; (2) whenever in his judgment the public interests of the Philippines require that such frequencies or wave lengths should be used for other purposes than those of the grantee, either by the Government of the Philippines or by other individuals or corporations licensed by it; (3) whenever in his judgment for any reason the public interests of the Philippines so require.\n(c) The Secretary of Public Works and Communications is authorized to appoint, employ or make use of such boards, to commissions, or agents as in his discretion he may select, to investigate, and determine the facts upon which he may act as aforesaid, and such boards, commissions, or agents shall have the right by compulsory process of subpoena, to summon witnesses, administer oaths, and take evidence."}},{"id":"PH-H956-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The stations of the grantee shall be so constructed and operated as to effect a minimum of interference with the wave lengths selected with a view to avoiding interference with existing stations and to permit the expansion of the grantee’s service."}},{"id":"PH-H956-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A special right is reserved to the Government of the Republic of the Philippines, in time of war, insurrection, or public disorder to take over and operate the said stations upon order and discretion of the President of the Philippines."}},{"id":"PH-H956-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The right is hereby reserved to the Government of the Philippines, through the Public Service Commission, or such other office as may be thereunto duly authorized, to fix the maximum and minimum rates to be charged by the grantee."}},{"id":"PH-H956-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings, and personal property, exclusive of the temporary permit, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further be liable to pay all other taxes under the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H956-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the National, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H956-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"No private property shall be taken for any purposes by the grantee without proper condemnation proceedings and just compensation paid or tendered therefore, and any authority to take and occupy land contained herein, shall not apply to the taking, use, or occupation of any land except such as required for the actual necessary purposes for which this franchise is granted."}},{"id":"PH-H956-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"It shall be unlawful for the grantee to use, employ, or contract, for the labor of persons held in involuntary servitude."}},{"id":"PH-H956-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines, and the right to use or occupy public property and places hereby granted shall revert to the respective governments, upon the termination of this temporary permit, by repeal or by forfeiture, or expiration in the due course."}},{"id":"PH-H956-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"As a condition of the granting of this franchise the grantee shall execute a bond in favor of the Government of the Philippines, in the sum of ten thousand pesos in form and with securities satisfactory to the Secretary of Public Works and Communications, conditioned upon the faithful performance of the grantee’s obligations hereunder during the first three years of the life of this franchise. If, after three years from the date of acceptance of this franchise, the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H956-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Acceptance of this franchise shall be given in writing within six months after approval of this Act. When so accepted by the grantee and upon the approval of the bond aforesaid by the Secretary of Public Works and Communications the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H956-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any company or corporations organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred, or assigned shall subject to all the conditions, terms, restrictions, and limitations of this franchise as fully and completely and to the same extent as if the franchise has been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H956-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This franchise shall not be interpreted to means an exclusive grant of the privileges herein provided for."}},{"id":"PH-H956-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play or other matter to be broadcast from its stations; but if any speech, play or other matter should constitute a violation of the law or infringement of a private part, the grantee shall be free from any liability, civil or criminal, for such speech, play or other matter: Provided, That the grantee, during any broadcast shall cut off from the air the speech, play or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the same thereof is indecent or immoral, and willful failure to do so shall constitute a valid cause for the cancellation of this permit."}},{"id":"PH-H956-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Philippine Standard Products Co,. Inc. a Franchise to Construct, Maintain and Operate a Radio Broadcasting Station in Manila, Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H957"] = {"id":"PH-H957","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1122_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"在八打雁省Cuenca市镇设立Don Juan村的法案","en":"An Act to Create the Barrio of Don Juan in the Municipality of Cuenca, Province of Batangas","orig":"An Act to Create the Barrio of Don Juan in the Municipality of Cuenca, Province of Batangas"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1122","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1122_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H957-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Lungos ng Parang, Kulit, Lumampao, Pisa, Napapanayam and Lagundian, in the municipality of Cuenca, Province of Batangas, are constituted into a barrio in the said municipality to be known as the barrio of Don Juan.\nThe boundaries of the said barrio shall be as follows:\n\"Starting at the boundary of municipalities of Alitagtag and Cuenca, from the shore of Lake Taal, thence following the aforesaid boundary line between the said municipality upward, until the point or boundary line between the sitio of Kulit and barrio of San Felipe, Cuenca, thence going Northward to the uppermost central part of Makatmon, thence including the entire portion of Maculot mountain facing Lake Taal to the boundary line between the sitios of Lagundian and Lagnas going downward following the aforestated boundary line to the share of Lake Taal.\""}},{"id":"PH-H957-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Create the Barrio of Don Juan in the Municipality of Cuenca, Province of Batangas","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H958"] = {"id":"PH-H958","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1123_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"进一步修订第186号联邦法（经修正）第11条第（a）款第3段，以及第660号共和国法（经修正）第26条第2款的法案","en":"An Act to Further Amend Paragraph Three, Subsection (a) of Section Eleven of Commonwealth Act Numbered One Hundred Eighty-Six as Amended, and the Second Paragraph of Section Twenty-Six Republic Act Numbered Six Hundred and Sixty, as Amended","orig":"An Act to Further Amend Paragraph Three, Subsection (a) of Section Eleven of Commonwealth Act Numbered One Hundred Eighty-Six as Amended, and the Second Paragraph of Section Twenty-Six Republic Act Numbered Six Hundred and Sixty, as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1123","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1123_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H958-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph three, subsection (a) of section eleven of Commonwealth Act Numbered One hundred eighty-six as amended, by the Republic Act Numbered Six hundred sixty, and further amended by Republic Act Numbered Seven hundred twenty-eight, is hereby further amended to read as follows:\n\"(3) For those who are at least sixty-five years of age, lump sum payment of present value of annuity for first five years and annuity thereafter to be paid monthly; and for those who are at least sixty-years of age and have rendered thirty-three years of service or more, the present value of the annuity for the first five years to be paid in five equal annual installments, each payable at the beginning of each year, and the annuity thereafter to be paid monthly; Provided, That said lump sum payment or annual installments of annuity may be made to a retired employee only if the premiums paid by and for him are sufficient to cover said payment or payments: Provided, further, That it shall be compulsory for an employer to pay on the date of retirement, in preference to all other obligations except salaries and wages of its employees, its share of at least the premiums required to permit an employee to enjoy this option.\""}},{"id":"PH-H958-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The second paragraph of section twenty-six of Republic Act Numbered Six hundred sixty, as amended by Republic Act Numbered Seven hundred twenty-eight, is hereby further amended to read as follows:\n\"Notwithstanding any provisions of this Act to the contrary, any member who was separated from the service as a consequence of the reorganization for in Republic Act Numbered Four hundred and twenty-two or as a consequence of the elimination of his position and salary in Republic Act Numbered Five hundred sixty-three, known as the General Appropriation Law for the fiscal year nineteen hundred and fifty-one, or by operation of any future Reorganization Act, may be retired under the provisions of this Act if qualified: Provided, That the period during which sum an officer or employee had been out of the service as a result of said reorganization, from the date of his separation to the date of his re-instatement or reappointment on or before December thirty-one, nineteen hundred and fifty-one, shall be considered as leave of absence: Provided, further, That any gratuity or retirement benefit already received by him shall be refunded to the System; Provided, furthermore, That contributions corresponding to his last five years of service shall be paid as provided in section twelve of Commonwealth Act Numbered One hundred and eighty-six, as amended. This provisions shall also apply to any member of the judiciary who, prior to the approval of this Act, was separated from the service after reaching seventy years of age and rendering at last thirty year of service and who is not entitled to retirement benefit under any law.\""}},{"id":"PH-H958-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Paragraph Three, Subsection (a) of Section Eleven of Commonwealth Act Numbered One Hundred Eighty-Six as Amended, and the Second Paragraph of Section Twenty-Six Republic Act Numbered Six Hundred and Sixty, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H959"] = {"id":"PH-H959","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1124_1954.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"设立国家教育委员会、负责制定普通教育政策并指导全国教育事务的法案","en":"An Act Creating a Board of National Education Charged with the Duty of Formulating General Education Policies and Directing the Educational Interests of the Nation","orig":"An Act Creating a Board of National Education Charged with the Duty of Formulating General Education Policies and Directing the Educational Interests of the Nation"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1124","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1124_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H959-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a Board of National Education which shall formulate, implement and enforce general educational objectives and policies, coordinate the offerings, activities and functions of all educational institutions in the country with a view to accomplishing an integrated, nationalistic and democracy-inspired educational system in the Philippines."}},{"id":"PH-H959-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Board of National Education shall be composed of fifteen members as follows:\n(a) The Secretary of Education\n(b) The Chairman of the Committee on Education in the Senate\n(c) The Chairman of the Committee on Education in the House of Representatives\n(d) The Director of Public Schools\n(e) The Director of Private Schools\n(f) The President of the University of the Philippines\n(g) the Chairman of the United Nations Educational, Scientific, and Cultural Organization’s National Commission of the Philippines.\n(h) Eight other members who shall be appointed by the President of the Philippines, with the consent of the Commission on Appointments, one from each of the following groups or organizations:\n1. Labor\n2. Industry or Management\n3. Agriculture\n4. National Catholic Educational Association\n5. Mohammedan or other cultural minority\n6. Philippine Association of Christian Schools\n7. Philippine Association of Colleges and Universities\n8. Teaching profession These eight members shall serve for a period of four years: Provided, That, in the first appointment, two members shall be appointed for one year, two or two years, two for three years, and two for four years."}},{"id":"PH-H959-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education or, in his absence, the Undersecretary of Education shall act as Chairman of the Board. The Chairman and members of the Board shall serve in an honorary capacity and shall receive no compensation or remuneration for their services as such, except that they shall be paid traveling expenses to and from meetings of the Board that they attend."}},{"id":"PH-H959-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Board shall have the following powers and functions:\n(a) To formulate the objectives and basic policies of education for children and adults in conformity with the philosophy and mandates of the Constitution.\n(b) To coordinate the objectives, functions and activities of different types and kinds of educational institutions in the Philippines.\n(c) To set up general goals of accomplishments for the entire Philippine school systems, the attainment of which shall be the objectives of the policies and functions of all educational institutions in the country."}},{"id":"PH-H959-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"It shall be the exclusive agency of the Government for the implementation of educational policies and the direction of the educational interests of the nation, subject only to the constitutional authority of the President of the Republic over executive departments, bureaus and offices."}},{"id":"PH-H959-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Chairman of the Board shall have the following duties and functions:\n(a) To call meetings of the Board and preside over them.\n(b) To execute or implement decisions of the Board, and to see to it that the educational policies approved by the Board are duly complied with and followed by all schools.\n(c) To perform all duties heretofore prescribed by law for the highest education officials of the land that are not inconsistent with the provisions of this Act.\n(d) To perform such other duties as may be assigned by the Board."}},{"id":"PH-H959-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Board shall appoint its Secretary and may request for the detail in its office of such personnel as it may need from the Department of Education or any Bureau of Office under it."}},{"id":"PH-H959-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"All acts, executive orders, administrative circulars or regulations inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H959-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The sum of one hundred thousand pesos, or so much thereof as may be necessary to carry out the purposes of this Act, is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated."}},{"id":"PH-H959-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating a Board of National Education Charged with the Duty of Formulating General Education Policies and Directing the Educational Interests of the Nation","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H960"] = {"id":"PH-H960","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1125_1954.html","fetchedAt":"2026-10-06","articleCount":24,"structureMode":"ARTICLE","title":{"zh":"设立税务上诉法院","en":"An Act Creating the Court of Tax Appeals","orig":"An Act Creating the Court of Tax Appeals"},"level":"law","status":"active","topics":["tax","judiciary"],"docNumber":"Republic Act No. 1125","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 24 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1125_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H960-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Court; Judges; qualifications; salary; tenure. - There is hereby created a Court of Tax Appeals which shall consist of a Presiding Judge and two Associate Judges, each of whom shall be appointed by the President, with the consent of the Commission on Appointments. The Presiding Judge shall be so designated in the commission issued to him by the President, and the Associate Judges shall have precedence according to the date o their commissions. The Presiding Judge shall receive a compensation of thirteen thousand pesos per annum and shall have the same qualifications, rank, category and privileges as the Presiding Judge of the Court of Industrial Relations. The Associate Judges shall each receive a compensation of twelve thousand pesos per annum and shall have the same qualifications, rank, category and privileges as a member of the Court of Industrial Relations. The Presiding Judge and the Associate Judges shall be appointed to hold office during good behavior, until they reach the age of seventy, or become incapacitated to discharge the duties of their office, unless sooner removed for the same causes and in the same manner provided by law for members of the judiciary of appellate rank."}},{"id":"PH-H960-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Quorum; temporary vacancy. - Any two Judges of the Court of Tax Appeals shall constitute a quorum, and the concurrence of two judges shall be necessary to promulgate any decision thereof. In case of temporary vacancy, disability or disqualification, for any reason, of any of the judges of the said Court, the President may, upon the request of the Presiding Judge, designate any Judge of First Instance to act in his place; and such Judge of First Instance shall be duly qualified to act as such."}},{"id":"PH-H960-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Clerk of court; appointment; qualification; compensation. - The Court of Tax Appeals shall have the Clerk of Court who shall be appointed by the President with the consent of the Commission on Appointments. No person shall be appointed Clerk of Court unless he is duly authorized to practice law in the Philippines. The Clerk of Court shall exercise the same powers and perform the same duties in regard to all matters within the court's jurisdiction, as are exercise and performed by clerks of Court of First Instance, in so far of those powers and the performance of those duties the clerk shall be under the direction of the said court. The Clerk of Court shall receive a compensation of six thousand pesos per annum."}},{"id":"PH-H960-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Other subordinate employees. - The Court of Tax Appeals shall appoint, in accordance with the Civil Service Law, rules and regulations, the necessary personnel to assist it in the performance of its duties. The said Court shall fix their salaries and prescribe their duties."}},{"id":"PH-H960-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Disqualifications. - No judge or other officer or employee of the Court of Tax Appeals shall intervene, directly or indirectly, in the management or control of any private enterprise which in any way may be affected by the functions of the Court. Judges of the said Court shall be disqualified from sitting in any case on the same grounds provided under Rule one hundred twenty-six of the Rules of Court for the disqualification of judicial officers. No person who has once serviced in the Court in a permanent capacity, either as Presiding Judge or as Associated Judge thereof, shall be qualified to practice as counsel before the Court for a period of one year from his separation therefrom for any cause."}},{"id":"PH-H960-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Place of office. - The Court of Tax Appeals shall have its office in the City of Manila, and shall hold hearings at such time and place as it may, by order in writing, designate with a view to assuring a reasonable opportunity for taxpayers to appear with a little inconvenience and expense as practicable."}},{"id":"PH-H960-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Jurisdiction. - The Court of Tax Appeals shall exercise exclusive appellate jurisdiction to review by appeal, as herein provided.\n(1) Decisions of the Collector of Internal Revenue in cases involving disputed assessments, refunds of internal revenue taxes, fees or other charges, penalties imposed in relation thereto, or other matters arising under the National Internal Revenue Code or other law or part of law administered by the Bureau of Internal Revenue;\n(2) Decisions of the Commissioner of Customs in cases involving liability for customs duties, fees or other money charges; seizure, detention or release of property affected fines, forfeitures or other penalties imposed in relation thereto; or other matters arising under the Customs Law or other law or part of law administered by the Bureau of Customs; and\n(3) Decisions of provincial or city Boards of Assessment Appeals in cases involving the assessment and taxation of real property or other matters arising under the Assessment Law, including rules and regulations relative thereto."}},{"id":"PH-H960-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Court of record; seal; proceedings. - The Court of Tax Appeals shall be a court of record and shall have a seal which shall be judicially noticed. It shall prescribe the form of its writs and other processes. It shall have the power to promulgate rules and regulations for the conduct of the business of the Court, and as may be needful for the uniformity of decisions within its jurisdiction as conferred by law, but such proceedings shall not be governed strictly by technical rules of evidence."}},{"id":"PH-H960-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Fees. - The Court shall fix reasonable fees for the filing of an appeal, for certified copies of any transcript of record, entry or other document, and for other authorized services rendered by the Court or its personnel."}},{"id":"PH-H960-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Power to administer oaths; issue subpoena; punish for contempt. - The Court shall have the power to administer oaths, receive evidence, summon witnesses by subpoena and require the production of papers or documents by subpoena duce tecum, subject in all respects to the same restrictions and qualifications as apply in judicial proceedings of a similar nature. The Court shall, in accordance with Rule sixty-four for the Rules of Court, have the power to punish for contempt for the same causes, under the same procedure and with the same penalties provided therein."}},{"id":"PH-H960-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Who may appeal; effect of appeal. - Any person association or corporation adversely affected by a decision or ruling of the Collector of Internal Revenue, the Collector of Customs or any provincial or city Board of Assessment Appeals may file an appeal in the Court of Tax Appeals within thirty days after the receipt of such decision or ruling.\nNo appeal taken by the Court of Appeals from the decision of the Collector of Internal Revenue or the Collector of Customs shall suspend the payment, levy, distraint, and or sale of any property of the taxpayer for the satisfaction of his tax liability as provided by existing law; Provided, however, That when in the opinion of the Court the collection by the Bureau of Internal Revenue or the Commissioner of Customs may jeopardize the interest of the Government and/or the taxpayer the Court at any stage of the proceeding may suspend the said collection and require the taxpayer either to deposit the amount claimed or to file a surety bond for not more than double the amount with the Court;"}},{"id":"PH-H960-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Taking of evidence. - The Court may, upon proper motion on or its initiative, direct that a case, or any issue thereof, be assigned to one of its members for the taking of evidence, when the determination of a question of fact arises upon motion or otherwise in any stage of the proceedings, or when the taking of an account is necessary, or when the determination of an issue of fact requires the examination of a long account. The hearing before such member shall proceed in all respects as though the same had been made before the Court.\nUpon the recommendation of such hearing such member, he shall promptly submit to the Court his report in writing, stating his findings and conclusions; and thereafter, the Court shall render its decisions on the case, adopting, modifying, or rejecting the report in whole or in part, as the case may be, or the Court may, in its discretion recommit it with instructions, or receive further evidence."}},{"id":"PH-H960-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Decision. - Cases brought before the Court shall be decided within thirty days after the submission thereof for decision. Decisions of the Court shall be in writing, stating clearly and distinctly the facts and the law on which they are based, and signed by the judges concurring therein. The Court shall provide for the publication of its decisions in the Official Gazette in such form and manner as may best be adopted for public information and use.\nAs in the case of judicial officers under section one hundred twenty-nine of the Administrative Code, the judges of the Court shall each certify on their applications for leave, and upon salary vouchers presented by them for payment, or upon the payrolls under which their salaries are paid, that all proceedings, petitions and motions which have been submitted to the Court for determination or decision for a period of thirty days or more have been determined or decided by the Court on or before the date of making the certificate, and no leave shall be granted and no salary shall be paid without such certificate."}},{"id":"PH-H960-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effect of decision that tax is barred by statute of limitations. - If the assessment or collection of any tax is barred by any statute of limitations, the decisions of the Court that effect shall be considered as its decision that there is no deficiency in respect of such tax."}},{"id":"PH-H960-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Publicity of proceedings and publication of decisions. - All decisions of, and all evidence received by the Court and its divisions, including transcript of stenographic reports of the hearings, shall be public records open to the inspection of the public, except that after the decision of the Court in any proceedings has become final the Court may, upon motion of the taxpayer or the Government permit the withdrawal, by the part entitled thereto of originals of books, documents and records, and or models, diagrams, and other exhibits, introduced in evidence before the Court or any division; or the Court may, on its own motion, make such other disposition thereof as it deems advisable. The Court shall provide for the publication of its decisions in the Official Gazette in such form and manner as may be best adopted for public information and use."}},{"id":"PH-H960-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Damages. - Where an appeal is found to be frivolous, or that proceedings have been instituted merely for delay, the Court may assess damage against the appellants in an amount not exceeding five hundred pesos, which shall be collected in the same manner as fines or other penalties authorized by law."}},{"id":"PH-H960-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Violation of penal law. - When, in the performance of its functions, it should appear to the Court that a crime or other violation of law has been committed, or, that there are reasonable grounds to believe that any official, employee or private person is guilty of any crime, offense or other violation, the Court shall refer the matter to the proper department, bureau or office for investigation or the institution of such criminal or administrative action as the facts and circumstances of the case may warrant."}},{"id":"PH-H960-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Appeal to the Supreme Court. - No judicial proceeding against the Government involving matters arising under the National Internal Revenue Code, the Customs Law or the Assessment Law shall be maintained, except as herein provided, until and unless an appeal has been previously filed with the Court of Tax Appeals and disposed of in accordance with the provisions of this Act.\nAny party adversely affected by any ruling, order or decision of the Court of tax Appeals may appeal therefrom to the Supreme Court by filing with the said Court a notice of appeal and with the Supreme Court a petition for review, within thirty days from the date he receives notice of said ruling, order or decision. If, within the aforesaid period, he fails to perfect his appeal, the said ruling, order or decision shall become final and conclusive against him If no decision is rendered by the Court within thirty days from the date a case is submitted for decision, the party adversely affected by said ruling, order or decision may file with said Court a notice of his intention to appeal to the Supreme Court, and if, within thirty days from the filing of said notice of intention to appeal, no decision has as yet been rendered by the Court, the aggrieved party may file directly with the Supreme Court an appeal from said ruling, order or decision, notwithstanding the foregoing provisions of this section.\nIf any ruling, order or decision of the Court of Tax Appeals be adverse to the Government, the Collector of Internal Revenue, the Commissioner of Customs, or the provincial or city Board of Assessment Appeals concerned may likewise file an appeal therefrom to the Supreme Court in the manner and within the same period as above prescribed for private parties.\nAny proceeding directly affecting any ruling, order or decision of the Court of Tax Appeals shall have preference over all other civil proceedings except habeas corpus, workmen's compensation and election cases."}},{"id":"PH-H960-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Review by certiorari. - Any ruling, order or decision of the Court of Tax Appeals may likewise be reviewed by the Supreme Court upon a writ of certiorari in proper cases. Proceedings in the Supreme Court upon a writ of certiorari or a petition for review, as the case may be, shall be in accordance with the provisions of the Rules of Court or such rules as the Supreme Court may prescribe."}},{"id":"PH-H960-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Appropriation. - The sum of seventy-thousand pesos is hereby appropriated out of any funds in the National Treasury not otherwise appropriated for the salaries and the purchase of supplies and equipment necessary for the operation of the Court of Tax Appeals herein established during the current fiscal year. Thereafter the funds necessary for the operation of the Court shall be included in the regular Appropriation Act."}},{"id":"PH-H960-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"General provisions. - Whenever the words \"Board of Tax Appeals\" are used in Commonwealth Act Numbered Four hundred and seventy, otherwise known as the Assessment Law, or in other laws, rules and regulations relative thereto, the same shall read \"Board of Assessment Appeals.\"\nThe Central Board of Tax Appeals created under section two of Commonwealth Act Numbered Five hundred and thirty is hereby abolished.\nExecutive Order Numbered Four hundred and one-A, dated the fifth of January, nineteen hundred and fifty- one, is repealed and the Board of Tax Appeals created therein, abolished: Provided, however, That all cases heretofore decided by the said Board of Tax Appeals and thence appealed to the Supreme Court pursuant to Executive Order Numbered Four hundred one-A shall be decided by the Supreme Court on the merits to all intents and purposes as if said Executive Order has been duly enacted by the Congress: And, Provided, further, That all cases now pending in the said Board of Tax Appeals shall be transferred to the Court of Tax Appeals and shall be heard and decided by the latter to all intents and purposes as if they had been originally filed therein.\nAny law or part of law, or any executive order, rule or regulation or part thereon, inconsistent with the provisions of this Act is hereby repealed."}},{"id":"PH-H960-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Pending cases to be remanded to Court. - All cases involving disputed assessment of Internal Revenue taxes or customs duties pending determination before the Court of First Instance shall be certified and remanded by the respective clerk of court to the Court of Tax Appeals for final disposition thereof."}},{"id":"PH-H960-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Separability Clause. - If any clause, sentence, paragraph or part of this act shall be adjudged by any court of competent jurisdiction to be invalid, such judgment shall not affect, impair or invalidate the remainder of this Act, but shall confined in its operations to the clause, sentence, paragraph or part thereof directly involved in the controversy."}},{"id":"PH-H960-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p13"};
  FT["PH-H961"] = {"id":"PH-H961","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1126_1954.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Two Million Four Hundred and Forty-Five Thousand Pesos for the Purchase and Installation of Automatic Telephone to Replace the Present Government Second-Hand and Obsolete Manual Telephone System, and for Other Purposes","orig":"An Act Appropriating Two Million Four Hundred and Forty-Five Thousand Pesos for the Purchase and Installation of Automatic Telephone to Replace the Present Government Second-Hand and Obsolete Manual Telephone System, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1126","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1126_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H961-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sums or so much thereof as be necessary are hereby appropriated, out of the general funds in the National Treasury, not otherwise appropriated, to be disbursed by the Bureau of Telecommunications for the purposes specified hereunder:\n(a) For the purchase of automatic telephone control office equipment and accessories, including cost of installation:\n(1) For the first year ₱800,000.00\n(2) For the second year ₱400,000.00 Total ₱l,200,000.00\n(b) For the purchase and installation of outside plant facilities (aerial and underground cable network, pole lines, etc.):\n(1) For the first year P350,000.00\n(2) For the second year ₱350,000.00 Total P700,000.00\n(c) For the purchase of telephone subscriber's instruments including installations:\n(1) For the first year ₱150,000.00\n(2) For the second year 150,000.00 Total ₱300,000.00\n(d) For the reconditioning of existing government buildings for use as telephone exchanges and/or for the construction of new buildings in case no available government buildings are suitable for such purpose as well as purchase of sites for buildings:\n(1) For the first year ₱100,000.00\n(2) For the second year 75,000.00 Total ₱175,000.00\n(e) For the purchase of installation, repair and maintenance tools and equipment and supplies, including such light and heavy line construction and intenance trucks as may be necessary for the above purpose:\n(1) For the first year ₱70,000.00 Total ₱70,000.00"}},{"id":"PH-H961-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the recommendation of the Secretary of Public Works and Communications, and with the approval president, excess in any item mentioned in section one hereof may be transferred to other items to cover shortages in the amounts appropriated therefor."}},{"id":"PH-H961-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All balances of the appropriations made in this remaining unexpended on June thirty, nineteen hundred fifty-seven, shall be available fox expenditures for this project until it is completed."}},{"id":"PH-H961-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The funds herein appropriated shall not be released unless and until the Secretary of Finance and the Auditor General shall have certified to the President that there are existing and available funds in the National Treasury for the purpose."}},{"id":"PH-H961-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 16, 1954."}}],"pack":"ph-p13"};
  FT["PH-H962"] = {"id":"PH-H962","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1127_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订San Pablo市宪章，使市长及市议会全体7名议员职位改为民选，并指定该议会议长为市长缺位或不能履职时的代理市长","en":"An Act Amending the Charter of the City of San Pablo so as to Make Elective the Position of Mayor and All the Seven Members of the Municipal Board and to Designate the Presiding Officer of the Said Board, the Acting Mayor in the Absence or Incapacity of the City Mayor","orig":"An Act Amending the Charter of the City of San Pablo so as to Make Elective the Position of Mayor and All the Seven Members of the Municipal Board and to Designate the Presiding Officer of the Said Board, the Acting Mayor in the Absence or Incapacity of the City Mayor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1127","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1127_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H962-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections seven, as amended, eight, eleven, as amended, and twelve of Commonwealth Act Numbered Five hundred and twenty, are amended to read as follows:\n\"Sec. 7. The mayor— His election and compensation. — The mayor shall be the chief executive of the city. He shall be elected at large by the qualified voters of the city during every election for provincial and municipal officials in conformity with the Revised Election Code. No person shall be elected Mayor, unless he is at least thirty years of age and a qualified voter therein.\n\"He shall receive a salary of not exceeding six thousand pesos a year. With the approval of the proper department head, the Mayor may be provided, in addition to his salary, a non-commutable allowance of not exceeding two thousand pesos per annum.\n\"Sec. 8. The Acting Mayor. — In the event of sickness, absence, or other temporary incapacity of the Mayor, the President of the Municipal Board shall perform the duties of the Mayor. In the event of a definitive vacancy in the position of Mayor, the President of the Philippines shall appoint a resident of the city of San Pablo to discharge the duties of the Mayor until said position shall be filled in accordance with law. If, for any reason, the duties of the office of the Mayor cannot be performed by the President of the Municipal Board, said duties shall be performed by the City treasurer. In case of the incapacity of the officials mentioned above to perform the duties of the Mayor, the President shall appoint or designate one, The Acting Mayor shall have the same powers, duties and compensation as the Mayor.\n\"Sec. 11. Constitution and organization of the Municipal Board—Compensation of members thereof .— The Municipal Board shall be the legislative body of the City and shall be composed of seven councilors who shall be elected at large by popular vote during every election for provincial and municipal officials in the conformity with the provisions of the Revised Election Code. The members of the Board shall elect from among themselves a president, who for one year shall preside at all meetings of the Board in which he is present. In his absence, the Board shall elect one of its members as temporary presiding officer. The president of the Municipal Board shall sign all the ordinances, and all resolutions and motions directing the payment of money or creating liability, enacted or adopted by the Board. In case of sickness, absence, suspension or other temporary disability of any member of the Board, or if necessary to maintain a quorum, the President of the Philippines may appoint a temporary substitute who shall possess all the rights and perform the duties of a member of the Board until the return to duty of the regular incumbent.\n\"If any member of the Municipal Board should be a candidate for office in any election, he shall be deemed to have renounced his membership in the Municipal Board except when he presents himself as candidate for the same position, in which case, he shall be incompetent to act with the Board in the discharge of the duties conferred upon it relative to election matters and the other members of the Board shall discharge said duties without his assistance, or they may choose some disinterested elector of the city to act with the Board in such matters in his stead.\n\"The President of the Municipal shall each receive a compensation of two thousand four hundred pesos per annum and the other members shall each receive a compensation of two thousand pesos per annum.\n\"The three councilors who were elected in the regular election for provincial and municipal officials in nineteen hundred and fifty-one shall continue in office until their successors shall have been elected and have qualified, and pending the next regular election for provincial and municipal officials, the President of the Philippines shall appoint with the consent of the Commission on Appointments the four other elective members of the Municipal Board.\n\"Sec. 12. Qualifications, election, suspension, and removal of members of the Board. — The members of the Municipal Board shall be qualified electors of the city and not less than twenty-three years of age. Upon qualifying, the members-elect shall assume office on the date fixed in the Election Code until their successors are elected and have qualified.\n\"If for any reason the election fails to take place on the date fixed by law, or such election results in a failure to elect one or more of the members, the President shall issue as soon as practicable a proclamation calling a special election to fill said office. Whenever the member-elect dies before assumption of office, or, having been so elected, his election is not confirmed by the President for disloyalty, or such member-elect fails to qualify for any reason, the President may in his discretion either call a special election or fill the office by appointment. Vacancies in the office shall be filled by appointment by the President of a suitable person belonging to the political party of the officer whom he is to replace.\n\"The members of the Municipal Board may be suspended or removed from office under the same circumstances, in the same manner, and with the same effect, as elective provincial officials, and the provisions of law providing for the suspension or removal of elective provincial officers are hereby made effective for the suspension or removal of said members of the Board.\""}},{"id":"PH-H962-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Republic Act Numbered Eight hundred seventy-nine is hereby repealed."}},{"id":"PH-H962-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending the Charter of the City of San Pablo so as to Make Elective the Position of Mayor and All the Seven Members of the Municipal Board and to Designate the Presiding Officer of the Said Board, the Acting Mayor in the Absence or Incapacity of the City Mayor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H963"] = {"id":"PH-H963","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1128_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第481号共和国法（即为菲律宾武装部队人员提供更有效牙科护理的法案）若干条的法案","en":"An Act to Amend Certain Sections of Republic Act Numbered Four Hundred Eighty-One, Entitled “An Act to Provide More Efficient Dental Care for the Personnel of the Armed Forces of the Philippines”","orig":"An Act to Amend Certain Sections of Republic Act Numbered Four Hundred Eighty-One, Entitled “An Act to Provide More Efficient Dental Care for the Personnel of the Armed Forces of the Philippines”"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 1128","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1128_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H963-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections two and five of Republic Act Numbered Four hundred eighty-one are amended to read as follows:\n\"Sec. 2. The Secretary of National Defense shall issue such regulations as may be necessary to carry out the intent of this Act, and the procedure for the performance of the dental functions of such dental service shall be defined and prescribed by appropriate directions to be issued by the Chief of Dental Service to the end that the dental service of the Armed Forces of the Philippines, shall study, plan and direct and all matters coming within the cognizance of such service and all matters relating to dentistry shall be referred to the dental service. The Chief of Dental Service shall be directly responsible to the Chief of Staff for the administrations of all matters related to the dental service. Hereafter the dental corps of the Armed Forces of the Philippines shall be known as the dental service.\n\"Sec. 5. The number of officers of the dental service shall not be less than two officers for every thousand of the total strength of the AFP authorized from time to time. A separate roster for officers of the dental service shall be kept separate from the medical service. Hereafter in time of war or other emergency the dental service shall consist of commissioned officers of the same grades and proportionately distributed among such grades as are now or may hereafter be provided for the medical corps, and who shall have the rank, pay and allowances of officers of corresponding grades in the medical corps.\""}},{"id":"PH-H963-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of Republic Act Numbered Four Hundred Eighty-One, Entitled “An Act to Provide More Efficient Dental Care for the Personnel of the Armed Forces of the Philippines”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H964"] = {"id":"PH-H964","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1129_1954.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将阿尔拜贸易学校改设为中级与大专层次的区域工艺学校，名称为Bicol区域工艺学校，并授权为此拨款的法案","en":"An Act Converting the Albay Trade School into a Regional School of Arts and Trades of Secondary and Collegiate Levels, to be Known as the Bicol Regional School of Arts and Trades and Authorizing the Appropriation of Funds for the Purpose","orig":"An Act Converting the Albay Trade School into a Regional School of Arts and Trades of Secondary and Collegiate Levels, to be Known as the Bicol Regional School of Arts and Trades and Authorizing the Appropriation of Funds for the Purpose"},"level":"law","status":"active","topics":["trade","education","culture"],"docNumber":"Republic Act No. 1129","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1129_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H964-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Albay Trade School is converted into a regional school of arts and trades of the Northern Luzon School of Arts and Trades type, to be known as the Bicol Regional School of Arts and Trades. The said school shall be under the supervision of the Bureau of Public Schools and subject to the provisions of the School Law. Courses of secondary and collegiate shall be offered in the said school."}},{"id":"PH-H964-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos, or so much thereof as may be necessary, is authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the Bicol Regional School of Arts and Trades during the school year 1954-1955. Such sums as thereafter may be needed for the same purpose shall be included in the annual General Appropriation Act."}},{"id":"PH-H964-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education is hereby empowered to make the necessary negotiations for the transfer without cost of such site, buildings, equipment, and other facilities of the Albay Trade School to the National Government, and to locate and acquire or cause to be located and acquired such additional site for the purpose of this Act which may be public or private lands situated within the Province of Albay."}},{"id":"PH-H964-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Albay Trade School into a Regional School of Arts and Trades of Secondary and Collegiate Levels, to be Known as the Bicol Regional School of Arts and Trades and Authorizing the Appropriation of Funds for the Purpose","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H965"] = {"id":"PH-H965","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1130_1954.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"设立反挂名董事会、规定其职责与职能并为其他目的法案","en":"An Act to Create an Anti-Dummy Board, to Prescribe its Duties and Functions, and for Other Purposes","orig":"An Act to Create an Anti-Dummy Board, to Prescribe its Duties and Functions, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1130","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1130_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H965-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created in the Department of Justice a board which shall be designated and known as the Anti-Dummy Board and which shall be vested with and shall exercise the powers and duties hereinafter specified. The Anti-Dummy Board shall be composed of the Secretary of Justice who shall be ex officio Chairman of the Board, and four other members to be appointed by the President of the Philippines with the consent of the Commission of Appointments.\nNo person shall be appointed a member of the Anti-Dummy Board unless he is a natural born citizen of the Philippines who has continuously resided in the Philippines not less than ten years before his appointment and he must be a citizen of good standing.\nThe tenure of office of members of the Board, with the exception of the Chairman, and the grounds of their separation shall be the same as these provided for in the case of Judges of Courts of First Instance."}},{"id":"PH-H965-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The main purpose of the Anti-Dummy Board shall be so insure the implementation of all the provisions of the Constitution, nationalization laws, and other legal provisions which require Philippine citizenship or citizenship of any other specific country for the exercise or enjoyment of a right, franchise or private, property or business, and further, to coordinate, as far as practicable all government agencies charged with the enforcement of the said provisions of the Constitution and laws and, in particular, Commonwealth Act Numbered One hundred and eight, as amended, commonly known as the Anti-Dummy Law, and to make and publish a list of all associations and corporations having their names, or under their control a right, franchise, privilege, property or business, the exercise or enjoyment of which is expressly reserved by the said constitution or laws to citizens of the Philippines, or of the United States, or to corporations or associations at least fifty-one per cent of the capital of which is owned by such citizens, with a view to eliminating or preventing entirely, the evasion of circumvention of the said Constitutional provisions and laws."}},{"id":"PH-H965-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Anti-Dummy Board shall have the following duties:\n(a) To investigate violations and prosecute all violators of the laws mentioned in section two of this Act, hereinafter called dummies.\n(b) To furnish professional services to informers who wish to avail themselves of section three-A of Commonwealth Act Numbered One hundred and eight, as inserted therein by Republic Act Numbered One hundred and thirty-four.\n(c) To enter as amicus curiae in all court cases which may have arisen from dummy cases.\n(d) To devise ways and means for the carrying out of an educational propaganda against dummies.\n(e) To devise ways and means for the carrying out of all nationalization legislation.\n(f) To organize local subcommittees in the chartered cities and municipalities and a provincial chapter in every capital of the provinces to help the Board in its campaigns against dummies.\n(g) To issue rules and regulations for the government of the Board and that of the subcommittees and chapters to be established under the provisions hereof; and\n(h) To perform such other duties as may enable the Board to carry out the purposes for which it has been created."}},{"id":"PH-H965-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In order to carry out its duties effectively, the Board shall be empowered to issue by itself or through any of its authorized investigators, subpoenas and subpoenas duces tecum, to designate any of its officers or investigators to administer oaths in the investigation of dummy cases and to examine the books and accounts of any person, association or corporation involved in said cases."}},{"id":"PH-H965-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Anti-Dummy Board shall have its main office in the City of Manila and shall meet at such time as it may designate. The presence of three members of the Board shall constitute a quorum for the transaction of any of its business. The Board shall distribute its work among its members by lot: Provided, That the Chairman shall exercise supervision over the other members of the Board.\nWith the exception of the Chairman of the Board, each member of the Board shall receive a salary of four thousand eight hundred pesos per annum: Provided, That if a member of the Board is a governmental official, he shall not receive extra compensation as such member."}},{"id":"PH-H965-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"There shall be a secretary-treasurer of the Anti-Dummy Board, who shall be a member of the Philippine Bar and who shall be appointed by the Board. The said officer shall receive an annual compensation of six thousand pesos. The duties of the secretary-treasurer shall be to keep full and correct minutes of all the proceedings of the Board: to pay out of the funds in his charge all properly approved accounts and, in general, to manage the funds entrusted to him by and in behalf of the board as authorized by law and regulations; and to perform such other duties as may be assigned to him by the Board.\nThe Anti-Dummy Board may appoint attorneys, investigators and other employees as it may deem necessary and fix their duties and salaries: Provided, That investigators appointed by the Board shall be lawyers, and/or certified public accountants, the proportion of the number of lawyers and accountants to be at the discretion of the Board. Each investigator shall receive a salary of at least three thousand six hundred pesos per annum.\nThe President may, upon recommendation of the Board, detail one or more assistant provincial fiscals or assistants attorneys under the Department of Justice, or any other employees in the National, provincial, city or municipal governments, on special duty with the Board. Employees so detailed shall perform such duty as is required under such detail, and the time so employed shall count as part of their regular official service."}},{"id":"PH-H965-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The permanent officials and employees of the Anti-Dummy Board and those detailed under special duty therewith, members of the Philippine Constabulary, members of the city, municipal and municipal district police, agents of the Bureau of Internal Revenue, agents of the Bureau of Immigration and such other officers and employees of the government as may be designated by the Chairman of the Board, are hereby made deputies of the Anti-Dummy Board, with full authority to enforce the provisions of sections three and four of this Act and the Nationalization Laws, and to arrest offenders against the same."}},{"id":"PH-H965-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"There is appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of two thousand pesos or so much thereof as may be necessary, to be placed at the disposal of the Board, subject to paragraph four, General Provisions, section seven of Commonwealth Act Numbered Two hundred and forty-six, as amended, for the payment of the salaries of the necessary personnel, for the purchase of necessary equipment and supplies, and for sundry expenses to be incurred to carry into effect the provisions of this Act during the fiscal year nineteen hundred and fifty-five. Thereafter, the necessary sum for the operation of the said Board shall be included in the General Appropriation Act."}},{"id":"PH-H965-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect on July 1, 1954.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Create an Anti-Dummy Board, to Prescribe its Duties and Functions, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H966"] = {"id":"PH-H966","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1131_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第679号共和国法（即《规定妇女与儿童就业、对违反者规定处罚并为其他目的法案》）第3条、第7条与第12条的法案","en":"An Act to Amend Sections Three, Seven and Twelve of Republic Act Numbered Six Hundred Seventy-Nine, Entitled “An Act to Regulate the Employment of Women and Children, to Provide Penalties for Violation Hereof, and for Other Purposes”","orig":"An Act to Amend Sections Three, Seven and Twelve of Republic Act Numbered Six Hundred Seventy-Nine, Entitled “An Act to Regulate the Employment of Women and Children, to Provide Penalties for Violation Hereof, and for Other Purposes”"},"level":"law","status":"active","topics":["labor","criminal","civil"],"docNumber":"Republic Act No. 1131","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1131_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H966-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section three, seven and twelve of Republic Act Numbered Six hundred seventy-nine are amended to read as follows:\n\"Sec. 3. Employment of persons below eighteen years of age. -(a) No woman below eighteen years shall be employed or permitted or suffered to work, with or without compensation, in any bar, night club, dance hall, dancing school for men, escort service, lodging house, massage clinic, hotel, resort or other place of work similar to the foregoing, as hostess, waitress, individual entertainer or escort for men, taxi-dancer, professional dance partner, attendant, or in any other similar capacity.\n\"(b) No child below eighteen years of age shall be employed or permitted of suffered to work in any pharmacy or laboratory for the preparation of drugs or pharmaceutical or chemical products.\n\"(c) No person below eighteen years of age shall be employed or permitted of suffered to work in any shop, factory, industrial or commercial establishment or other place or labor— \"(1) where the work is done in connection with the preparation of, or involves contamination with, any noxious, poisonous, infectious or explosive substances; or \"(2) where the work, not otherwise specified in this Act, involves serious danger to the life or health of the employee, as the Secretary of Labor may determine after consultation with representatives of employers and employees or organizations thereof.\n\"For the purpose of paragraph (2) of subsection (c) of this section, the Secretary of Labor shall from time to time issue orders specifying the occupations which he determines would involve serious danger to the life or health of the employees and shall cause such orders to be published in newspapers of general circulation or by such other means as he deems reasonably calculated to give intersected persons generally notice of such issuance. Any such order shall take effect thirty days after entry thereof.\n\"Sec. 7. Employment of women. — (a) No woman, regardless of age, shall be employed in any shop, factory, commercial or industrial establishment or other place of labor to perform work which requires the employee to work always standing or which involves the lifting of heavy objects.\n\"(b) No woman, regardless of age, shall be employed or permitted or suffered to work, with or without compensation, in any industrial undertaking or branch thereof between ten o’clock at night and six o’clock in the morning of the following day, except those who are immediate members of the family operating or owning the same. An employer may be exempted from the requirement of this subsection— \"(1) in case of force majeure causing an interruption in the work which was not foreseen and which is not of a securing character;\n\"(2) by the secretary of Labor, if he finds, after the proper investigation, that the work has to do with raw materials or materials in the course of treatment and which are subject to rapid deteriorations and night work is necessary to preserve such materials from loss; and \"(3) by the President of the Philippines, with or without the recommendation of the Secretary of Labor, in case of emergency where the national interests demand the suspension of the night work prohibition for women in a particular industry or industries.\"(c) No woman, regardless of age, shall be employed or permitted or suffered to work, with or without compensation, in any commercial or non-industrial and undertaking or branch thereof, other than agricultural, between twelve o’clock midnight and seven o’clock in the morning of the following day, except those who are immediate members of the family owning or operating the same.\n\"(d) No woman, regardless of age, shall be employed or permitted or suffered to work in any agricultural undertaking at night time without giving her a period of rest of not less than nine consecutive hours.\n\"The prohibition against night work for women provided for in subsections (b), (c) and (d) hereof shall not apply to— \"(1) women holding responsible positions of a managerial or technical character; and \"(2) women employed in health and welfare services.\n\"(c) In any shop, factory, commercial, industrial, non-industrial, or agricultural establishment or other place of labor where mean and women are employed, the employer shall not discriminate against any woman in respect to terms and conditions of employment on account of her sex, and shall pay equal remunerations for work of equal value for both men and women employees.\n\"Sec. 12. Violation and penalties. — (a) It shall be unlawful for any employer: (1) to discharge any woman employed by him for the purpose of preventing such woman from enjoying the benefits of sections seven or eight of this Act; (2) to discharge such woman on account of her pregnancy, or while on leave or in confinement due to her pregnancy, or (3) to discharge or refuse the admission of such woman upon returning to her work for fear that she may again the pregnant.\n\"(b) It shall be unlawful for any employer to discharge any women or child employed by him for having filed a complaint under this Act or to discharge such woman or child or any other employee who has given testimony or is about to give testimony under this Act.\n\"(c) It shall be unlawful for any employer to discharge any women or child employed by him for any other cause which is not attributable to the fault of such employee or worker.\n\"(d) Any violation of any provisions of this Act shall be punished by a fine of not less than one hundred pesos nor more than five thousand pesos, or by imprisonment for not less than thirty days nor more than one year, or by both such fine and imprisonment, in the discretion of the Court.\n\"If the violation is committed by a firm, association or corporation, the manager or, in his default, the person acting as such, shall be liable.\""}},{"id":"PH-H966-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Sections Three, Seven and Twelve of Republic Act Numbered Six Hundred Seventy-Nine, Entitled “An Act to Regulate the Employment of Women and Children, to Provide Penalties for Violation Hereof, and for Other Purposes”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H967"] = {"id":"PH-H967","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1132_1954.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"授权巴科洛德市举债或发行不超过六百万比索的债券，以资助该市海滨土地围填","en":"An Act Authorizing the City of Bacolod to Contract an Indebtedness or to Issue Bonds in the Amount not Exceeding Six Million Pesos to Finance the Reclamation of Foreshore Lands in Said City","orig":"An Act Authorizing the City of Bacolod to Contract an Indebtedness or to Issue Bonds in the Amount not Exceeding Six Million Pesos to Finance the Reclamation of Foreshore Lands in Said City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1132","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1132_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H967-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to implement Republic Act Numbered One hundred sixty-one, which authorizes the City of Bacolod to undertake the reclamation of foreshore lands as its own expense, the Government of the City of Bacolod is hereby authorized to contract an indebtedness with any person, association, corporation or money lending institution, or to issue bonds in the amount not exceeding six million pesos to raise funds with which to finance such reclamation of foreshore lands bordering the City of Bacolod in order to establish and provide proper and adequate docking and harbor facilities for interisland and ocean-going vessels calling at the aforesaid city. All lands reclaimed as herein provided except such as may be necessary for roads, parks and other public improvements, shall be sold or leased to the public under such rules and regulations as the City of Bacolod may prescribe. All the proceeds derived from the sale or lease of such land shall be credited to a special fund which shall be used exclusively for the payment of all obligations in connection with said land reclamation project, and the balance thereof shall be credited to a special public works fund to be used exclusively for public works for the improvement of the City of Bacolod."}},{"id":"PH-H967-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In case the City of Bacolod shall decide to issue bonds, the Secretary of Finance, in consultation with the Monetary Board of the Central Bank of the Philippines, shall prescribe the form, the rate of interest, call and redemption features, and all other terms and conditions of issuance, placement, sale, servicing, redemption features, and payment of all bonds issued under the authority of this Act.\nThe bonds issued under the authority of this Act may be made payable both, as to the principal and interest, in Philippine currency or any readily convertible foreign currency.\nNothing in this section shall be interpreted to mean that the Secretary of Finance, in the redemption of securities, is prevented from applying the lottery principle by which bonds, drawn by lot, may be redeemed before maturity either at their face value or above.\nThe bonds to be issued under this Act shall be exempt from taxation by the Government of the Republic of the Philippines or by any political or municipal subdivision thereof, which fact shall be stated on their face value in accordance with this Act under which said bonds are issued."}},{"id":"PH-H967-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"A sinking fund shall be established in such manner that the annual contributions thereto, accrued as at such rate of interest as may be determined by the Secretary of Finance in consultation with the Monetary Board, shall be sufficient to redeem at maturity the bonds issued under this Act. Said fund shall be under the custody of the Central Bank of the Philippines which shall invest the same in such manner as the Monetary Board may approve; shall charge all expenses of such investment to said sinking fund; and shall credit the same with interest on investments and other income belonging to it."}},{"id":"PH-H967-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The provisions of existing law to the contrary notwithstanding, the Director of Public Works shall have the supervision of all work to be done and improvements to be made under the provisions of this Act."}},{"id":"PH-H967-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the City of Bacolod to Contract an Indebtedness or to Issue Bonds in the Amount not Exceeding Six Million Pesos to Finance the Reclamation of Foreshore Lands in Said City","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H968"] = {"id":"PH-H968","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1133_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第920号共和国法第1条C编第（a）款伊洛伊洛省第I组第（h）项的法案","en":"An Act to Amend Item (h), Group I, for the Province of Iloilo, Subsection (a), Title C, Section One of Republic Act Numbered Nine Hundred Twenty","orig":"An Act to Amend Item (h), Group I, for the Province of Iloilo, Subsection (a), Title C, Section One of Republic Act Numbered Nine Hundred Twenty"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1133","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1133_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H968-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item (h), Group I, for the Province of Iloilo, subsection (a), Title C, section one of Republic Act Numbered Nine hundred twenty is amended to read as follows;\n\"(h) For the roadside development of the Dingle-San Enrique road, including the improvement of the Moroboro Spring and the establishment of a traveler’s rest-house ₱25,000.00\""}},{"id":"PH-H968-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Item (h), Group I, for the Province of Iloilo, Subsection (a), Title C, Section One of Republic Act Numbered Nine Hundred Twenty","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H969"] = {"id":"PH-H969","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1134_1954.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为菲律宾武装部队军官提供年资津贴的法案","en":"An Act to Provide for Longevity Pay to Officers of the Armed Forces of the Philippines","orig":"An Act to Provide for Longevity Pay to Officers of the Armed Forces of the Philippines"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 1134","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1134_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H969-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Hereafter each officer of the Armed Forces of the Philippines shall receive in addition to his monthly base pay longevity pay equivalent to ten per centum of the monthly base pay authorized for his grade for each five years of faithful and efficient service heretofore or hereafter rendered as an officer or the Armed Forces of the Philippines and of recognized guerrilla units, such additional pay to be compounded every five years; Provided, That the total amount of longevity pay shall not exceed fifty per centum of the officer’s monthly base pay as prescribed by law: Provided, further, That nothing in this section shall be construed as authorizing payment of any back longevity pay for any period of services heretofore rendered."}},{"id":"PH-H969-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For purposes of this Act, the sum total of the active tours of duty of reserve officers shall be counted."}},{"id":"PH-H969-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section five (d) of Republic Act Numbered Two hundred ninety-one is hereby repealed."}},{"id":"PH-H969-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect on July 1, 1954.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for Longevity Pay to Officers of the Armed Forces of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H970"] = {"id":"PH-H970","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1135_1954.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"设立菲律宾烟草管理局、界定其目标、权力与职能并为其他目的法案","en":"An Act Establishing the Philippine Tobacco Administration, Defining its Objectives, Powers and Functions, and for Other Purposes","orig":"An Act Establishing the Philippine Tobacco Administration, Defining its Objectives, Powers and Functions, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1135","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1135_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H970-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Name and domicile. — There is hereby created the \"Philippine Tobacco Administration\", called for short the PTA, which shall be organized within sixty days after the approval of this Act. It shall have its main office in the City of Manila, and such branches an agencies within and outside of the Philippines as may be necessary for the proper conduct of its business. The PTA shall be under the supervision of the Administrator of Economic Coordination."}},{"id":"PH-H970-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Purpose and objectives. — The PTA shall have the following purposes and objectives:\n(a) To promote the effective merchandising of leaf tobacco in the domestic and foreign markets so that those engaged in the industry will be placed on a basis of economic security;\n(b) To conduct researches on tobacco and tobacco products in all its phases, either agricultural or industrial, for the purpose of: (1) introducing into the agronomy and industry of tobacco such practices or processes as will increase the yield and quality of the leaves and products, thus reducing the cost of production but materially increasing the profit; (2) developing strains of different types of tobacco seeds through intensive breeding and selection from native and imported stocks; and (3) utilizing and converting factory by-products which are for the present allowed to go to waste into varied articles of economic value, thus achieving greater production and efficiency in the industry;\n(c) To improve existing methods of manufacture of tobacco products, such as the preparations of aged leaves for manufacture and the improvement of existing blends of cigars and cigarettes;\n(d) To establish and maintain efficient balanced relation between production and consumption of tobacco leaves and tobacco products, and such marketing conditions as will insure and stabilize the price at a level sufficient to cover the cost of production plus reasonable profit;\n(e) To insure a permanent, sufficient and balanced production of tobacco leaves, tobacco products and by-products for local consumption and exportation;\n(f) To create warehousing and marketing facilities in suitable centers and supervise the selling and buying of leaves produced by the farmers on bidding basis;\n(g) To supervise and control the classification and grading of leaf tobacco in the packing establishments of wholesome tobacco dealers, exporters, large plantation owners, and auction floors, in accordance with existing rules and regulations; and\n(h) To improve the living and economic conditions of the laborers engaged in the tobacco industry by gradual and effective correction of the inequalities in the industry.\nPowers"}},{"id":"PH-H970-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Specific and general powers. -For carrying out the purposes mentioned in the preceding section, the PTA shall have the following powers:\n(a) To establish, keep, maintain and operate such experiment stations and seed farms in any part of the Philippines as may be necessary to undertake extensive research in tobacco culture and curing, including studies on the feasibility of merchandising tobacco farms, development of suitable tobacco varieties and strains suited for the different tobacco regions, control and eradication of tobacco pests and diseases, reduction of the cost of production, and the agronomical studies inherent with the culture of this crop;\n(b) To establish, maintain and/or subsidize a chemical tobacco research laboratory for industrialization studies on processing, fermentation and aging to produce a quality leaf for the factories: Provided, That this phase of the work shall be under the care and supervision of the Institute of Science and Technology, which shall from time to time submit programs of studies to the PTA for approval and assignment of funds to carry out such programs;\n(c) To purchase, make invent such machineries and materials, equipment and supplies as may be necessary to prosecute successfully its researches and experimental work;\n(d) To expand and explore the domestic and foreign trades for tobacco leaves, tobacco products and by-products to assure mutual benefits to consumers and producers, and to promote and maintain a sufficient general production of tobacco leaves, tobacco products and by-products by an efficient coordination of the component elements of the tobacco industry of the Philippines;\n(e) To buy sell, assign, own, operate, rent or lease, subject to existing laws, machineries, equipment, materials, merchant vessels, rails, railroad lines and other equipment and materials necessary for the production, processing, manufacture, handling and transportation and warehousing of tobacco leaves, tobacco products and by-products;\n(f) To grant loans and credits, on reasonable terms, to tobacco planters when it deems such loans advisable;\n(g) To enter, make and execute contracts of any kind as may be necessary or incidental to the attainment of its purposes with any person, firm, or public or private corporation, with the government of the Philippines or of the United States, or of any state, or with any person therefrom, or with any foreign government with treaties with the government of the Philippines;\n(h) To buy, process, and age, and sell all tobacco leaves, as well as stabilize and guarantee prices of just cured tobacco leaves, based on grades;\n(i) To provide credit facilities to registered tobacco planters directly or through credit cooperative associations or any other financial institutions;\n(j) To promote, foster and encourage the organization of cooperative associations among tobacco planters, producers or dealers;\n(k) To act as agent, broker or commission merchant of producers cooperative associations or act as tobacco manufacturers agent;\n(l) To do all such things, transact all such business and perform such functions directly or indirectly necessary, incidental or conducive to the attainment of the purposes of the PTA; and\n(m) Generally, to exercise all the powers of a corporation under the Corporation Law, insofar as they are not inconsistent with the provisions of this Act.\nGoverning Body"}},{"id":"PH-H970-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Composition and appointment. -The powers of the PTA shall be vested in, and exercised by, a Board of Directors consisting of five members to be appointed by the President with the consent of the Commission on Appointments. The President of the Philippines shall appoint the Chairman of the Board from among its members who shall act as the General Manager. Of the five directors first appointed as above prescribed, the President of the Philippines shall designate one to serve for one year, one for two years, one for three years, one for four years, and one for five years; and thereafter, each director appointed shall serve for five years. Whenever a vacancy shall occur among the directors, the person appointed to fill it shall hold office for the unexpired term of the member whose place is selected to fill. Any director shall be subject to removal by the President of the Philippines. Three members of the Board of Directors shall constitute a quorum for the transaction of business. Before entering upon the discharge of their duties, each of the directors shall take the oath prescribed by law. The members of the Board shall each receive a per diem of not to exceed twenty pesos for each day of meeting actually attended by them, except the General Manager who shall receive a salary of not to exceed twelve thousand pesos per annum; Provided, That the meetings of the Board shall not exceed four meetings a month; Provided, further, That the provisions of paragraph one—General Provisions section seven of Commonwealth Act Numbered Two hundred forty-six to the contrary notwithstanding, no officer or employee of the Government receiving a fixed compensation or salary from public funds and serving as director of the Administration shall be paid the per diem herein provided. Directors of the Administration shall not be allowed to receive more than one hundred pesos per month in per diem."}},{"id":"PH-H970-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers and duties of the Board of Directors. -The Board of Directors shall have the following powers:\n(a) To prescribe, amend, modify or repeal by-laws, rules and regulations, not inconsistent with the provisions of this Act, governing the manner in which the general business of the PTA may be exercised, subject to the approval of the Administrator of Economic Coordination;\n(b) To appoint and fix the compensation of the Assistant General Manager, subject to the approval of the Administrator of Economic Coordination and consent of the President of the Philippines, and to appoint and fix the compensation of the other officers of the PTA with the approval of the Administrator of Economic Coordination;\n(c) To approve the annual budget of the PTA and/or such supplemental budgets thereof as may be submitted to the Board by the General Manager from time to time; and\n(d) To perform such other duties as may be assigned to it by the President of the Philippines and/or by the Administrator of Economic Coordination.\nManagement"}},{"id":"PH-H970-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Managing head. -The Management of the PTA shall be vested in the General Manager."}},{"id":"PH-H970-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Powers and duties of the General Manager. -The duties of the General Manager shall be:\n(a) To direct and manage the affairs of the PTA on behalf of the Board of Directors and subject to its control and supervision;\n(b) To submit within sixty days after the close of the fiscal year an annual report to the Administrator of Economic Coordination, through the Board of Directors;\n(c) To appoint and fix the number and salaries, with the approval of the Board of Directors, of such subordinate employees as may be necessary for the proper discharge of the duties and functions of the PTA;\n(d) To suspend or otherwise discipline, for cause, any subordinate employee of the PTA; and\n(e) To perform such other duties as may be assigned to him by the Board of Directors from time to time."}},{"id":"PH-H970-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Powers and Duties of the Assistant General Manager. -The Assistant General Manager shall assist the General Manager and shall perform such other duties as may be assigned to him by the General Manager and/or the Board of Directors. The Assistant General Manager shall be at the same time head of one of the departments of the PTA, to be designated by the Board, and shall be technically trained along tobacco work. He shall act as General Manager in case of temporary absence or incapacity of the latter, and when the Assistant General Manager acts as General Manager he shall sit in all meetings of the Board of Directors and participate in the deliberations, but without the right to vote.\nAppointments and Promotions"}},{"id":"PH-H970-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Basis. -In the appointment and promotion of officers and employees of the PTA, merit, seniority and efficiency shall serve as basis, and no political test or qualification shall be prescribed and considered for such appointments and promotions. Any person appointed by the Board or by the General Manager in violation of this prohibition shall be removed by the Administrator of Economic Coordination, and the official responsible for such violation shall be suspended or removed from office by the President of the Philippines."}},{"id":"PH-H970-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Applications of Civil Service Law and Rules. -All officers and employees of the Administration shall be subject to the Civil Service Law and Rules, except those whose positions may, upon recommendation of the Board of Directors, be declared by the President of the Philippines as policy determining, primarily confidential or highly technical in nature.\nBooks of Accounts, Purchases and Contracts"}},{"id":"PH-H970-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Books of Accounts. -The PTA shall, at all times, maintain complete and accurate books of accounts, which shall be segregated under the five main accounts, namely:\n(a) Account No. 1, pertaining to the PTA activities in the stabilization of prices;\n(b) Account No. 2, pertaining to the PTA activities in the development and improvement of production;\n(c) Account No. 3, pertaining to the PTA activities in the promotion and economic and social conditions of the people engaged in the production of tobacco;\n(d) Account No. 4, pertaining to production of tobacco leaves ready for manufacture, industrialization programs, etc.; and\n(e) Account No. 5, pertaining to development of trade within and outside of the Philippines."}},{"id":"PH-H970-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Purchases and contracts. -All purchase and contracts for supplies or services, except for personal services, made by the PTA, shall be made after advertising in such a manner and at such times sufficiently in advance of opening of bids as the Board shall determine to be adequate to insure notice and opportunity for competition: Provided, That advertisement shall not be required, and purchases may be made in the open market in the manner common among business houses: (1) when an emergency requires immediate delivery of the supplies or performance of the service; or (2) when repair parts, accessories, supplemental equipment, or services are required for supplies or services previously furnished or contracted for; or (3) when the aggregate amount involved in any purchase of supplies or procurement of services does not exceed five hundred pesos: Provided, further, That in comparing bids and in making awards, the Board may consider such factors as relative quality, adaptability, skill, experience, record or integrity, ability to furnish repairs and/or maintenance services, the time of delivery or performance offered, and whether the bidder has complied with the specifications: Provided, further, That in case supplies may be procured from a government, domestic or foreign, and it can be established to the satisfaction of the PTA that the government price is the lowest possible, considering quality and period of delivery, purchases from such government may be made without public bidding.\nAudit"}},{"id":"PH-H970-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Personnel. -The Auditor General shall appoint a representative who shall be the Auditor of the PTA, and the necessary personnel to assist and representative in the performance of his duties. The salary of such auditor and the number and salaries of said personnel shall be determined by the Auditor with the advice of the Board of Directors. In case of disagreement, the matter shall be submitted to the President of the Philippines, whose decision shall be final. Said salaries and all other expenses of maintaining the Auditor’s office shall be paid by the PTA."}},{"id":"PH-H970-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Report. -The financial transaction of the PTA shall be audited in accordance with law, administrative regulations, and the principles and procedures applicable to commercial corporate transactions. A report of audit for each fiscal year shall be submitted, within sixty days after the close of the fiscal year, through the Auditor General, to the Board of Directors of the PTA, and copies thereof shall be furnished to the President of the Philippines, the Administrator of Economic Coordination and the Presiding Officers of the two Houses of Congress. The report shall set forth the scope of the audit and shall include a statement of assets and liabilities, capital and surplus or deficit; a statement of surplus or deficit analysis; a statement of income and expenses; a statement of sources and application of funds; and such comments and information as may be necessary, together with such recommendations with respect thereto as may be advisable, including a report of any impairment of capital noted in audit. The report shall also show specifically and program, expenditures or other financial transaction or undertaking observed in the course of audit which, in the opinion of the Auditor, has been carried on or made without authority of law and/or contrary to existing regulations, whether or not authorized by the Board of Directors.\nFunds"}},{"id":"PH-H970-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Capitalization. -To carry out the purpose of this Act there is created a special fund to be known as the \"Tobacco Industry Promotion Fund\" which shall be taken from taxes derived from the tobacco industry to be made available as follows: two million pesos, which is hereby appropriated, and, thereafter, an annual appropriation of two million pesos is authorized for a period of four years.\nThis Fund will be appointed in the following manner:\nTwenty per cent will be spent for operating expenses;\nSeventy per cent will be used for tobacco trading; and Ten per cent for researches to improve the tobacco industry in all its phases.\nThere shall be added to the capital of this Philippine Tobacco Administration all the funds, assets and properties still available belonging to the defunct National Tobacco Corporation.\nDissolution and Liquidation"}},{"id":"PH-H970-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Liquidation. -When the PTA is dissolved by law, it shall nevertheless continue as a body corporate for three years after the time of its dissolution, for the purpose of prosecuting and defending suits by or against it, and enabling it gradually to settle and close its affairs, and to dispose of and convey its properties, but not for the purpose of continuing the business for which it was established. Upon dissolution of the PTA, a Board of Liquidators shall be appointed by the President of the Philippines to take charge of winding up its corporate affairs and effecting its liquidation, and all the transactions of this Board shall be subject to the supervision and control of the Administrator of Economic Coordination."}},{"id":"PH-H970-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Reversion to General Funds. -All funds resulting from the dissolution and liquidation of the PTA, as herein Provided, shall revert to the general fund of the National Government.\nMiscellaneous Provisions"}},{"id":"PH-H970-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Applicability of the Corporation Law. -The provisions of the Corporation Law which are not inconsistent with the provisions of this Act shall be applicable to the PTA."}},{"id":"PH-H970-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Repealing Clause. -All Act, executive orders, administrative orders, proclamations, rules and regulations, or parts thereof, inconsistent with any of the provisions of this Act are repealed or modified accordingly."}},{"id":"PH-H970-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Separability clause. -If any provisions of this Act or the application of such provision to any person or circumstance is declared unconstitutional, the remainder of the Act or the application of such provision to other persons or circumstances shall not be affected by such declaration."}},{"id":"PH-H970-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Effectivity. -This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing the Philippine Tobacco Administration, Defining its Objectives, Powers and Functions, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H971"] = {"id":"PH-H971","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1136_1954.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"重组卫生部结核病司的法案","en":"An Act Reorganizing the Division of Tuberculosis in the Department of Health","orig":"An Act Reorganizing the Division of Tuberculosis in the Department of Health"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 1136","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1136_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H971-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Division of Tuberculosis in the Department of Health, hereinafter called the Division, is re-organized to include an administrative section with a statistical, motor and electrical maintenance, library, and buildings and grounds maintenance units; a section of clinics and therapy; a section of prevention and immunization with a BCG immunization and children’s clinic, and health education and social service units; a section of X-ray operation and maintenance; and a section of TB laboratory and research.\nThe Division shall have a chief and an assistant chief who shall be appointed by the Secretary of Health and shall receive annual compensation at the rate of seven thousand two hundred pesos and six thousand pesos, respectively. It shall also have such technical, clerical and other personnel as may be determined by the Secretary of Health who shall appoint them and fix their compensation in accordance with law; Provided, However, That all the subordinate personnel of the present Division of Tuberculosis in the Department of Health shall continue in office with at least the same compensation."}},{"id":"PH-H971-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Division shall have the following functions:\n(a) To coordinate, direct, and implement a well-balanced, comprehensive and intensive scheme of tuberculosis control services in the country, including prevention by direct (BCG immunization) and direct methods, diagnosis, treatment, social rehabilitation, public health training (for laymen and medical personnel) research, epidemiological and statistical studies, and national and international pooling of information;\n(b) To establish and maintain at least thirty fully-equipped, fully-manned provincial TB centers within four years, complete with diagnostic laboratory, X-ray and treatment facilities (surgical and non-surgical), giving free services;\n(c) To operate and supervise wards for TB patients in provincial hospitals where there are provincial TB centers;\n(d) To establish and maintain at least thirty mobile X-ray units within four years in order to reach rural areas with no access to the chest center;\n(e) To establish and maintain at least thirty mobile TB prevention units to undertake mass BCG immunization of susceptible children and young adults, intensive health education of the public by all possible means (loudspeaker attached to wagons, lectures, movies, leaflets,) home-visiting by home-visitors in rural areas, and gathering of epidemiological information on TB;\n(f) To establish and maintain at least six village rest settlements, in strategic and suitable geographic areas in all the three principal regions of the Philippines, for patients with initial or convalescing tuberculosis who have no place in sanitaria or hospitals, and to facilitate their rehabilitation and replacement, as well as those of their families, into normal society by teaching them gainful occupations under proper medical control;\n(g) To establish and maintain a National Tuberculosis Center to serve as the central headquarters for the direction of public health tuberculosis work throughout the country, to receive all reports, and statistical and epidemiological information, to serve as training center in tuberculosis for all categories of public health workers in the country;\n(h) To pool all information on tuberculosis and exchange such information with other countries; and\n(i) To cooperate with all agencies, governmental and voluntary, in matters of general public health welfare."}},{"id":"PH-H971-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is created the National Advisory Council on Tuberculosis to be composed of the Secretary of Health, as Chairman, one representative each of the Department of Labor, Department of Education, and Social Welfare Administration, to be designated by their respective heads, a representative of the Philippine Tuberculosis Society, and a representative each of two civic organizations to be designated by the President of the Philippines. The chief of the Division of Tuberculosis shall be the executive secretary of the National Advisory Council on Tuberculosis. The said Council shall give advice to the Division regarding the performance of its functions."}},{"id":"PH-H971-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The FOA-PHILCUSA and WHO-UNICEF-assisted TB and BCTG units when they are ready to the turned over fully to the Government, all tuberculosis clinics supported by provincial or city agreements if the provinces and cities concerned agree, and all the TB public health activities of the Department of Health, Department of Education, and Social Welfare Administration are transferred to the Division of Tuberculosis as herein reorganized. The said Division is authorized and directed to receive, staff, and maintain any TB center or pavilion which the Philippine Tuberculosis Society may turn over voluntarily to the Division."}},{"id":"PH-H971-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In lieu of the appropriations for the present Division of Tuberculosis in the Department of Health, there is appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of two million five hundred thousand pesos, or so much thereof as may be necessary, to carry out the purposes of this Act for the fiscal year nineteen hundred fifty-five. The necessary sum for the operation of the Division in subsequent years shall be included in the General Appropriation Act."}},{"id":"PH-H971-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reorganizing the Division of Tuberculosis in the Department of Health","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H972"] = {"id":"PH-H972","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1137_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第733号联邦法的法案","en":"An Act to Amend Commonwealth Act Numbered Seven Hundred and Thirty-Three","orig":"An Act to Amend Commonwealth Act Numbered Seven Hundred and Thirty-Three"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1137","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1137_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H972-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Commonwealth Act Numbered Seven hundred and thirty-three is hereby to read as follows:\n\"Sec. 1. Acceptance of, and authority to formally execute, the Executive Agreement.— The Executive Agreement which the President of the Philippines and the President of the United States have agreed to enter into pursuant to Title IV of Public Law Three hundred seventy-one—Seventy-ninth Congress, approved April thirty, nineteen hundred forty-six, entitled \"An Act to provide for the trade relations between the United States and the Philippines, and other purposes, as hereinbefore set forth, is hereby accepted and approved, and the President of the Philippines is authorized to formally execute the same on or after July fourth, nineteen hundred and forty-six. For the purpose of securing a revision of the aforesaid Agreement, without prejudice to its termination should a mutually satisfactory revision not be obtained, and notwithstanding the provisions of section two hereof enacting and continuing in effect as laws of the Philippines during the effectiveness of the said Agreement sections three hundred and eleven and three hundred and twelve of the Philippine Trade Act of nineteen hundred and forty-six, the duty free treatment provided for in Article I, Paragraph 1, of the Agreement shall apply in lieu of the treatment provided for in Article I, Paragraph 2, subparagraphs (a) and (b), to United States articles, entered or withdrawn from warehouses in the Philippines for consumption, during such period after the third day of July, nineteen and fifty four, but not after the thirty-first day of December, nineteen hundred and fifty-five, as the President may declare by proclamation to be a period during which Philippine articles, as defined in subparagraph (f) of Paragraph 1 of the Protocol, other than specified in items D to G, both inclusive, of the schedule to Article II, will be admitted into the United States free of customs duty, as such duly is defined in the Agreement, and during which the application of subparagraph (b) of Paragraph 2, Article II, if it should be applied by the United States, will not substantially impair the national economy: Provided, That any such proclamation shall be without prejudice to subparagraphs (a) and (b) of Paragraph 2, Article I, being considered as having been in effect for the purpose of applying the provisions of subparagraph (c) of Paragraph 2, Article I, of the Agreement.\""}},{"id":"PH-H972-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Commonwealth Act Numbered Seven Hundred and Thirty-Three","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H973"] = {"id":"PH-H973","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1138_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订《行政法典》若干条款（经第164号共和国法修正），涉及契约登记官办公室的法案","en":"An Act to Amend Certain Sections of the Administrative Code, as Amended by Republic Act Numbered One Hundred Sixty-Four, Relative to Offices of Registers of Deeds","orig":"An Act to Amend Certain Sections of the Administrative Code, as Amended by Republic Act Numbered One Hundred Sixty-Four, Relative to Offices of Registers of Deeds"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1138","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1138_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H973-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one hundred ninety-two, one hundred ninety-two (b), and two hundred one of the Administrative Code, as amended by Republic Act Numbered One hundred sixty-four, are hereby amended to read as follows:\n\"Sec. 192. Office of register of deeds. -There shall be one register of deeds for each city and one for each province, except in the Mountain Province, where there shall be two: one for the Subprovince of Benguet and another for the rest of the province: Provided, However , That the register of deeds of the City of Baguio or whoever performs his duties shall be ex-officio register of deeds for the Subprovince of Benguet, and that the register of deed of a province whose capital is a chartered city or whoever is acting in his place shall likewise be ex-officio register of deeds for said city.\n\"There shall be one deputy register of deeds in each of the registers of the City of Manila, Quezon City, the provinces of Cebu, Iloilo, Negros Occidental, Pangasinan and Rizal, and also in each registry with a yearly average collection of more than thirty thousand pesos, whenever in the judgment of the Secretary of Justice the needs of the service so demand. The deputy register of deeds shall be in classified service and shall be appointed by the Secretary of Justice, upon recommendation of the Chief of the General Land Registration Office.\"\n\"Sec. 192. (b) Salaries of registers of deeds. -The salary of the register of deeds of the City of Manila shall be seven thousand two hundred pesos per annum; (1) that of the registers of deeds of the Provinces of Iloilo, Negros Occidental, and Rizal, and Quezon City, six thousand pesos per annum; (2) that of the register of deeds of the Province of Pangasinan, five thousand four hundred pesos per annum; (3) that of the registers of deeds of the Provinces of Bulacan, Cebu, Nueva Ecija, Pampanga, Quezon, and Tarlac, and Pasay City, four thousand eight hundred pesos per annum; (4) that of the registers of deeds of the Provinces of Batangas, Camarines Sur, Capiz, Cavite, Davao, Ilocos Norte, Isabela, and Laguna, four thousand two hundred pesos per annum; (5) that of the registers of deeds of the Province of Albay, Antique, Bataan, Bohol, Cagayan, Camarines Norte, Cotabato, Ilocos Sur, La Union, Leyte, Mindoro Oriental, Misamis, Oriental, Negros Oriental, Nueva Vizcaya, Sorsogon, Zambales, and Zamboanga del Norte, the Cities of Baguio, Dagupan, Lipa, Ormoc, San Pablo, and Zamboanga, three thousand six hundred pesos per annum; and (6) that of the registers of deeds of other cities and provinces, three thousand pesos per annum.\n\"The salary of the deputy register of deeds in the City of Manila, shall be five thousand four hundred pesos per annum, and those of the deputy registers of deeds in other cities or provinces shall be three rates lower than those of their respective principals in the scale of salaries herein provided.\n\"From time to time but not oftener than once every five years the rats of salary of the registers of deeds, except in the City of Manila, shall be revised and fixed by the Secretary of Justice in accordance with the following schedule; (a) Six thousand pesos per annum for the registers of deeds whose yearly average collections during the last three years immediately preceding the year in which the revision is made have been seventy-five thousand pesos or more; (b) five thousand four hundred pesos per annum for those whose yearly average collections during the same period have been fifty thousand pesos or more but less than seventy-five thousand pesos; (c) four thousand eight hundred pesos per annum for those whose yearly average collections during the same period have been thirty thousand pesos or more but less than fifty thousand pesos; (d) four thousand two hundred pesos per annum for those whose yearly average collections during the same period have been fifteen thousand pesos or more but less than thirty thousand pesos; (e) three thousand six hundred pesos per annum for those whose yearly average collections during the same period have been five thousand pesos or more but less than fifteen thousand pesos; and (f) three thousand pesos per annum for those whose yearly average collections during the same period have been less than five thousand pesos. The rates of salary so revised and fixed shall be included in the General Appropriation Act for the fiscal year next following the year in which the revision is made: Provided, However, That the salary of the register of deeds of the City of Baguio shall be fixed on the basis of the consolidated yearly average collections of the registries of the City of Baguio and the Subprovince of Benguet, and that the salary of the register of a province who is ex-officio register of deeds for the city which is the capital of said province, shall likewise be fixed on the basis of the consolidated yearly average collections of the registries of said province and city.\n\"Sec. 201. Discharge of duties of register of deeds in case of vacancy, etc. -Until a regular register of deeds shall have been appointed for a city or province, or in case of vacancy in the office, or upon the occasion of the absence, illness, suspension, or inability of the register of deeds to discharge his duties, said duties shall be performed by the following officials, in the order in which they are mentioned below, unless the Secretary of Justice designate another official to act temporarily in the place:\n\"(a) For the city or province where there has been appointed a deputy register of deeds, by the said deputy register of deeds;\n\"(b) For the City of Baguio, by the city of attorney, assistant city attorneys, city treasurer or assistant city treasurer of Baguio;\n\"(c) For cities which are not provincial capitals, by the city attorney, assistant city attorney, city treasurer or assistant city treasurer;\n\"(d) For provinces in general, by the provincial fiscal, assistant provincial fiscal, provincial treasurer, or assistant provincial treasurer.\n\"In case of absence, disability or suspension of the register of deeds, without pay, or in case of vacancy in the position, the Secretary of Justice may, in his discretion, authorize the payment of an additional compensation to the official acting as register of deeds, such compensation, with his actual salary shall not exceed the salary authorized for the position thus filled by him.\""}},{"id":"PH-H973-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos, or so much thereof as may be necessary, is hereby appropriated, out of any funds existing in the National Treasury not otherwise appropriated, to be made available for carrying into effect the salary increases provided for in this Act."}},{"id":"PH-H973-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 16, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of the Administrative Code, as Amended by Republic Act Numbered One Hundred Sixty-Four, Relative to Offices of Registers of Deeds","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H974"] = {"id":"PH-H974","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1139_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"拨款支付1955年国际民用航空组织在马尼拉召开第二次北太平洋区域空中航行会议及国际航空运输便利化司第四次会议费用的法案","en":"An Act to Appropriate Funds to Bear the Expenses of Holding the Second North Pacific Regional Air Navigation Meeting and the Fourth Session of the Facilitation of International Air Transport Division Meeting to be Convened by the International Civil Aviation Organization at Manila in Nineteen Hundred and Fifty-Five","orig":"An Act to Appropriate Funds to Bear the Expenses of Holding the Second North Pacific Regional Air Navigation Meeting and the Fourth Session of the Facilitation of International Air Transport Division Meeting to be Convened by the International Civil Aviation Organization at Manila in Nineteen Hundred and Fifty-Five"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1139","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1139_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H974-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated the sum of one hundred fifty thousand pesos to bear the expenses of holding the Second North Pacific Regional Air Navigation meeting and the Fourth Session of the Facilitation of Air Transport Division meeting to be convened by the International Civil Aviation Organization at Manila in nineteen hundred and fifty-five, and such other expenses as shall be necessary to carry into effect the purposes of this Act."}},{"id":"PH-H974-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Appropriate Funds to Bear the Expenses of Holding the Second North Pacific Regional Air Navigation Meeting and the Fourth Session of the Facilitation of International Air Transport Division Meeting to be Convened by the International Civil Aviation Organization at Manila in Nineteen Hundred and Fifty-Five","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H975"] = {"id":"PH-H975","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1140_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将巴拉望省Bacuit市镇更名为El Nido的法案","en":"An Act Changing the Name of the Municipality of Bacuit in the Province of Palawan to El Nido","orig":"An Act Changing the Name of the Municipality of Bacuit in the Province of Palawan to El Nido"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1140","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1140_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H975-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Bacuit, Province of Palawan is hereby changed to El Nido."}},{"id":"PH-H975-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Municipality of Bacuit in the Province of Palawan to El Nido","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H976"] = {"id":"PH-H976","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1141_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将八打雁省 八打雁市镇 Libjo村 Malitam小村改设为村的法案","en":"An Act to Convert the Sitio of Malitam, in the Barrio of Libjo, Municipality of Batangas, Province of Batangas, into a Barrio","orig":"An Act to Convert the Sitio of Malitam, in the Barrio of Libjo, Municipality of Batangas, Province of Batangas, into a Barrio"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1141","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1141_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H976-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Malitam, in the barrio of Libjo, municipality of Batangas, Province of Batangas, is converted into a barrio to be known as the barrio of Malitam."}},{"id":"PH-H976-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Convert the Sitio of Malitam, in the Barrio of Libjo, Municipality of Batangas, Province of Batangas, into a Barrio","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H977"] = {"id":"PH-H977","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1142_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"在联合国教科文组织技术援助下设立社区学校培训中心，设于邦阿西楠省 Bayambang 市镇的法案","en":"An Act to Establish a Training Center for Community Schools with the Technical Assistance of the Unesco to be Located at the Municipality of Bayambang, Province of Pangasinan","orig":"An Act to Establish a Training Center for Community Schools with the Technical Assistance of the Unesco to be Located at the Municipality of Bayambang, Province of Pangasinan"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1142","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1142_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H977-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Secretary of Education is hereby authorized to establish and maintain with the technical assistance of the United Nations Educational, Scientific, and Cultural Organization, a training center for community schools to be located at the Municipality of Bayambang, Province of Pangasinan."}},{"id":"PH-H977-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish a Training Center for Community Schools with the Technical Assistance of the Unesco to be Located at the Municipality of Bayambang, Province of Pangasinan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H978"] = {"id":"PH-H978","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1143_1954.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"规定证券交易委员会更有效实施《证券法》及其他法律的法案","en":"An Act to Provide for a More Effective Administration of the Securities Act and Other Laws by the Securities and Exchange Commission","orig":"An Act to Provide for a More Effective Administration of the Securities Act and Other Laws by the Securities and Exchange Commission"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1143","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1143_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H978-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In addition to the powers, duties and functions presently vested in it by existing laws, the Securities and Exchange Commission, hereinafter referred to as the Commission, shall have the power:\n(a) To punish summarily for contempt by a fine not exceeding two hundred pesos or by imprisonment not exceeding ten days, or both, any person guilty of misconduct in the presence of the Commissioner of Securities and Exchange or official thereof conducting a hearing or investigation or so near the same as to interrupt the proceeding before them, including cases in which a person present at a hearing or investigation held by either of the said Commissioner or official refuses to be sworn as a witness or to answer a question when lawfully required to do so. To enforce the provisions hereof the Commission may, if necessary request the assistance of the Municipal Police for the execution of any order made by said Commissioner or official for the purpose.\n(b) To penalize any violation of or non-compliance with any terms of conditions of any certificate, license, or permit issued by the commission or of any order, decision, ruling or regulation thereof, by a fine of not exceeding two hundred pesos per day for every day during which such violation of default continues; and the Commission is hereby authorized and empowered to impose and collect such fine after due notice and hearing.\nThe fine so imposed shall be paid to the Government of the Philippines through the Commission, and failure to pay the fine with the time specified in the order or decision of the Commission shall be deemed good and sufficient reason for the suspension of the certificate, license or permit issued by the Commission until payment shall be made. In case the violation or default is committed by a corporation or association, the manager or the person who has charge of the management of the corporation or association and the officers or directors thereof who have ordered or authorized the violation or default shall be solidarily liable. Payment may also be enforced by appropriate action brought in a court of competent jurisdiction. The remedy herein provided shall not be a bar to, or affect any other remedy provided under existing laws but shall be cumulative and additional to such remedy or remedies.\n(c) In any investigation or hearing, by its order in writing, to cause the depositions of witnesses residing within or without the Philippines to be taken in the manner prescribed by the Rules of Court. Where witnesses reside in a place distant from Manila and it would be inconvenient and expensive for them to appear personally before the Commission, the Commission may also by proper order, commission any clerk of Court of First Instance, municipal judge or justice of the peace of the Philippines to take depositions of such witnesses in any case pending before the Commission. It shall be the duty of the official so commissioned, to designate promptly a date or dates for the taking of such depositions, giving timely notice to the parties, and on said date to proceed to take the depositions, reducing them to writing. After the depositions have been taken, the official so commissioned shall certify to the correctness of the depositions thus taken and forward the same as soon as possible to the Commission. It shall be the duty of the respective parties to furnish stenographers for taking and transacting the testimony taken. In case there are not stenographers available, the testimony shall be taken by such person as the clerk of court, municipal judge or justice of the peace may designate. The Commission may also commission a notary public to take the depositions in the manner herein provided.\n(d) To conduct all hearings and investigations in accordance with the rules adopted by the Commission, and in performing the same, it shall not be bound by technical rules of legal evidence.\n(e) To act on complaints for any violation of law, rule or regulation required to be enforced by it or for non-compliance of any term or condition of any certificate, license, or permit issued by it, free of charge. Where, however, the complaint or petition seeks the grant of affirmative relief, a nominal fee of ten pesos may be charged and collected by the Commission.\n(f) Subject to the approval of the Department of Head, to make such rules and regulations as may be necessary for the proper execution of all the laws administered by it.\n(g) To require all corporations and associations whose certificates or permits to sell securities were lost during the last World War II, including those issued by the National Treasurer under the Blue Sky Law, to file new registration statements of such securities in accordance with such forms as may be provided by the Commission, for which it shall charge and collect a fee of one-twentieth of one per centum of the aggregate par or issued value of the securities."}},{"id":"PH-H978-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For the effective implementation of this Act, the position of Assistant in the Securities and Exchange Commission is hereby converted to that of Deputy Commissioner of the Securities and Exchange Commission, hereinafter known as Deputy Commissioner. The Deputy Commissioner shall be appointed by the President of the Philippines with the consent of the Commission on Appointments, and shall receive a compensation of ten thousand pesos per annum. The Deputy Commissioner shall act in the absence, illness or incapacity of the Commissioner of Securities and Exchange and shall discharge such other functions and duties as may be entrusted to him by the latter. The Securities and Corporation Division of the Commission shall hereafter be known as the Legal and Enforcement Division. Said Division shall have a chief who shall be known as the Chief Legal Counsel and who shall receive a compensation of eight thousand four hundred pesos per annum, and eight attorneys, four of whom shall receive a compensation of five thousand four hundred pesos per annum each, and four, a compensation of four thousand five hundred pesos per annum each."}},{"id":"PH-H978-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Commissioner, the Deputy Commissioner, the chiefs of division, and the attorneys of the Commission, shall have the power to administer oaths in all matters under the jurisdiction of the Commission."}},{"id":"PH-H978-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In addition to the sum already appropriated for the Commission under the General Appropriation Act for the fiscal year nineteen hundred and fifty-four and nineteen hundred and fifty-five, the sum of twenty-eight thousand one hundred eighty pesos, is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated for the purposes of this Act."}},{"id":"PH-H978-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All acts or parts of acts inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H978-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for a More Effective Administration of the Securities Act and Other Laws by the Securities and Exchange Commission","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H979"] = {"id":"PH-H979","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1144_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Funds for Lighthouse Stations of the Republic of the Philippines","orig":"An Act Appropriating Funds for Lighthouse Stations of the Republic of the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1144","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1144_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H979-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sums, or so much thereof as may be necessary, are hereby appropriated out of the Port Works Funds\" that have accrued under Act Numberd Three thousand five hundred and ninety-two, as amended not otherwise appropriated, to be spent by the Secretary of Public Works and Communications subject to the provisions of this Act for the purposes mentioned hereunder:\n(a) For the construction, reconstruction, repair and improvement of installations in the following lighthouse stations, including the purchase of necessary materials and equipment:\n1.\nMalinao (front), Albay—Repair and painting of keeper's dwelling and tower ₱2,000.00\n2.\nSula Port, Albay—Repair and painting of dwelling and construction of new kitchen wings 4,000.00\n3.\nUngay Point, Rapu-Rapu, Albay—Repair and painting of existing keepers' dwelling, kitchen, store room and tower 6,000.00\n4.\nNogas Island, Antique—Construction of new keepers' dwelling, repair of batteries' house and painting of tower 12,000.00\n5.\nMariveles, Bataan—Construction of new 32-ft. R. C. tower 5,000.00\n6.\nCape Santiago, Batangas—Repair and painting of existing structures 3,000.00\n7.\nMalabrigo Point, Batangas—Repair of existing keepers' dwelling 4,000.00\n8.\nTagbilaran, Bohol—Repair of tower foundation 5,000.00\n9.\nCape Engano, Cagayan—Completion and painting of existing structures 5,000.00\n10.\nLinao Point, Cagayan—Completion or rehabilitation of structure 1,000.00\n11.\nPata Point, Cagayan—Repair of existing structures 10,000.00\n12.\nCanimo Island, Camarines Norte—Repair of all structures on the station 5,000.00\n13.\nSiaiat, Catanduanes—Completion or rehabilitation and construction of protection works 10,000.00\n14.\nCapiz Jetty and Culasi Point, Capiz—Construction of tower and repair and painting of existing structures 12,000.00\n15.\nCapitancillo, Cebu—Conversion of resent storage room to generator room, and repair and painting of tower 4,000.00\n16.\nTanguingui, Cebu—Repair of all structures in the station 15,000.00\n17.\nCotabato, Cotabato—Erection of steel tower 2,000.00\n18.\nCape San Agustin, Davao—Construction of new keepers' dwelling and water tank 12,000.00\n19.\nCape Bojeador, Ilocos Norte—Conversion of present oil room to engineer room 10,000.00\n20.\nCurrimao Point, Ilocos Norte—Construction of new 32-ft. R. C. tower 5,500.00\n21.\nBaliguian, Iloilo—Repair and painting of existing keepers' dwelling, kitchen, toilet, bodega, tower, and flagpol 10,000.00\n22.\nCalabazas Island, Iloilo—Construction of new 5,000 gal. R. C. water tank 2,000.00\n23.\nManigonigo Island, Iloilo—Painting of the steel tower 1,000.00\n24.\nSiete Pecados Island, Iloilo—Repair and painting of keepers' dwelling, generator room, and kitchen 5,500.00\n25.\nSan Fernando Point, La Union—Conversion of present storage room into a batteries room 1,000.00\n26.\nBaltazar Island, Marinduque—Repair of existing keepers' dwelling 1,000.00\n27.\nBugui Point, Masbate—Conversion of existing storage building into engine house and repair and painting of structures 3,000.00\n28.\nColorado Point, Masbate—Construction of new keepers' dwelling and repair and painting of existing tower 12,000.00\n29.\nJintotolo Island, Masbate—Conversion of present storage building into engine house 1,000.00\n30.\nMatabao, Masbate—Construction of keepers' dwelling and painting of existing structures 12,000.00\n31.\nSan Miguel, Masbate—Repair of dwelling and construction of new bodega 7,000.00\n32.\nAmbulong, Mindoro Occidental—Conversion of present storage building into engine house and general repair work 4,000.00\n33.\nApo Reef, Mindoro Occidental—Conversion of one of the present kitchen rooms into engine room and painting of structures 2,000.00\n34.\nCape Calabite, Mindoro Occidental—Repair and painting of present structures 2,000.00\n35.\nGolo Island, Mindoro Occidental—Construction of new keepers' quarters 12,000.00\n36.\nDumali Point, Mindoro Oriental—Repair and painting of existing installations 2,000.00\n37.\nEscarseo Point, Mindoro Oriental—Construction of the keepers' quarters (dwelling building) and kitchen-dining room building 12,000.001\n38.\nApo Island, Negros Oriental—Construction of the keepers' quarters (dwelling-building) and kitchen-dining room building 12,000,00\n39.\nLangoy Island, Palawan—Construction of new keepers' dwelling and power house 12,000.00\n40.\nBalabac Island, Palawan—Repair and painting of existing installation 5,000.00\n41.\nEspina Point, Palawan—Painting of structures 1,000.00\n42.\nManucan Island, Palawan—Construction of new keepers' quarters 12,000.00\n43.\nTubbataha Reef, Palawan—Construction of new keepers' quarters, repair of sea wall, and painting of tower 16,000.00\n44.\nCape Bolinao, Pangasinan—Repair of keepers' quarters, tower and toilet sheds 8,000.00\n45.\nApunan Point, Romblon—Conversion of present storage building into power house 1,000.00\n46.\nCorcuera Point, Romblon—Repair and painting of dwelling and kitchen 3,000.00\n47.\nGorda Point, Romblon—Construction of new keepers' dwelling 10,000.00\n48.\nBatag Island, Samar—Reconstruction of keepers' quarters 5,000.00\n49.\nCabilison Island, Samar—Construction of new quarters (dwelling) repair of kitchenm shed and painting of tower 12,000.00\n50.\nCapul Island, Samar—Reconstruction of present concrete building, kitchen shed, and storage building 8,500.00\n51.\nDivinubo Island, Samar—Repair of present quarters and storage room 1,500.00\n52.\nSan Bernardino, Samar—Repair of present keepers' quarters 6,000.00\n53.\nSuluan, Samar—Construction of newkeepers' quarters 12,000.00\n54.\nBagato, Sorsogon—Repair and painting of kitchen and storeroom 3,000.00\n55.\nCagayan, Sulu—Repair of tower and dwelling 4,000.00\n56.\nPearl Bank, Sulu—Repair and painting of keepers' quarters 1,000.00\n57.\nSaluag Island, Sulu—Construction of new keepers's dwelling 9,000.00\n58.\nCapones Island, Zambales—Reconstruction of existing structures 15,000.00\n59.\nLa Monha, Zambales—Construction of new 32 ft. R. C. tower and batteries room 5,000.00\n60.\nSubic Bay, Zambales—Conversion of part of kitchen and storage room into engine room 1,000.00\n61.\nSibago, Basilan City—Construction of new quarters' and watchmans' shed 13,000.00\n62.\nMalamawi, Basilan City—Repair of dwelling and construction of new R. C. tower 8,000.00\n63.\nPasig River, Manila—Construction of keepers' quarter 3,000.00\n64.\nCorregidor, Manila—Repair of kitchen and dining room 12,000.00 ₱421,000.000 (b) For the emergency repair and reconstruction and the survey and investigation of lighthouse stations and other aids to navigation including: the purchase of necessary materials and equipment and the payment of salaries, wages and sundry expenses of the lighthouse floating personnel in the central office at Manila, to be allotted by the Secretary of Public Works and Communications in accordance with the recommendations of the Lighthouse Board 166,000.00 (c) For the construction of new light houses 50,000.00 Grand Total ₱637,000.00"}},{"id":"PH-H979-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All sums appropriated under section one of this Act shall be released only after certification by the Secretary of Finance and the Auditor General to the"}}],"pack":"ph-p13"};
  FT["PH-H980"] = {"id":"PH-H980","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1145_1954.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"设立菲律宾椰子管理局、订明其权力、职能与职责并为其运营筹集必要资金的法案","en":"An Act Creating the Philippine Coconut Administration, Prescribing its Powers, Functions and Duties, and Providing for the Raising of the Necessary Funds for its Operation","orig":"An Act Creating the Philippine Coconut Administration, Prescribing its Powers, Functions and Duties, and Providing for the Raising of the Necessary Funds for its Operation"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 1145","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1145_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H980-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Name, duration and domicile. -A corporation is hereby created which shall be known as the Philippine Coconut Administration, hereafter called the PHILCOA, which shall be organized within sixty days after the approval of this Act and shall be under the direct supervision of the Office of Economic Coordination. It shall have its main office in the city of Manila, and such branches and agencies within or outside the Philippines, as may be necessary for the proper conduct of its business."}},{"id":"PH-H980-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Purposes and objectives. -The PHILCOA shall have the following purposes and objectives:\n(a) To ensure the steady and orderly development of the coconut industry, and to stabilize and strengthen its position in the world markets;\n(b) To promote the effective merchandising of copra, coconut oil, coconut products and by-products in the domestic and foreign markets so that those who are engaged in the coconut industry will be placed on a basis of economic security; Provided, However, That the PHILCOA may not engage in trading in any form without the prior approval of the President of the Philippines, which approval may be given only after prior recommendation of the National Economic Council;\n(c) To improve the tenancy relations between coconut proprietors and tenants and the living conditions of laborers engaged in the coconut industry;\n(d) To encourage the invention of useful machinery that will hasten the development of the coconut industry.\nPowers"}},{"id":"PH-H980-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Specific and general powers. -In order to carry out the proposes mentioned in the preceding section, the PHILCOA shall have the following powers:\n(a) To establish, keep, maintain and operate, or help establish, keep, maintain and operate, one central experiment station and such number of regional experiment stations in the coconut-producing areas of the Philippines as may be necessary to undertake extensive research in coconut culture, the control and eradication of coconut pests, the improvement of copra, the manufacture of coconut products and by-products, and the greater utilization of the coconut for new purposes: Provided, that the PHILCOA may utilize for the purposes herein set forth existing governmental research agencies;\n(b) To purchase of fabricate such machineries, materials, equipments and supplies as may be necessary to prosecute successfully such researches and experimental works;\n(c) To explore and expand the domestic and foreign markets for coconut products and by-products, to assure mutual benefit to consumers and producers, and to promote and maintain an efficient production of copra, oil and coconut by-products, by an effective coordination of the component elements of the coconut industry of the country;\n(d) To allocate, with the approval of the President of the Philippines, sums of money in favor of any research institution, governmental or private, to undertake researches on any phase of the coconut industry for specified purposes, Provided, That exclusive ownership rights to the results of such research shall accrue to the PHILCOA as provided for under section fourteen;\n(e) To regulate the marketing and exportation of copra by establishing standards for domestic trade and export and, pursuant hereto, to conduct an inspection through its agencies of all copra proposed for export to determine if they conform to the standards established.\n(f) To help planers and processors organize themselves into associations and cooperatives with a view to giving them greater control in the marketing of their products, and to help them obtain more credit facilities;\n(g) To enter, make and execute contracts of any kinds as may be necessary or incidental to the attainment of its purposes; and\n(h) Generally to exercise all the powers necessary to attain the purposes for which it is organized."}},{"id":"PH-H980-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Special authority to undertake projects and incur debts. -Upon the recommendation of the National Economic Council and with the approval of the President of the Philippines, the PHILCOA may directly engage in such projects and undertakings as may be deemed vital or necessary to the early attainment of its general objective; and for the purpose of financing such projects, the PHILCOA may borrow the necessary funds from any financial institutions subject existing rules and regulations; Provided, That the total loan outstanding at any one time shall not exceed ten million pesos.\nGoverning Body"}},{"id":"PH-H980-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Composition and appointment. -All corporate powers of the PHILCOA shall be vested in, and exercised by a Board of Administrators consisting of five members to be appointed by the President with the consent of the Commission on Appointments, three of whom shall be coconut planters; Provided, That no person appointed to this board may serve as director or more than two government or semi-government corporations. The President shall designate from among the members of the Board its Chairman."}},{"id":"PH-H980-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Tenure and compensation. -The members of the Board shall serve as designated by the President of the Philippines in their respective appointments for a term of four years, but any person to fill a vacancy shall serve only for the unexpired term of the member whom he succeeds. The Chairman shall receive a salary of twelve thousand pesos per annum and each member of per diem of twenty-five pesos for every meeting actually attended: Provided, That no member shall earn more than one hundred pesos a month in per diems; Provided, further, That if the member is a public official, he shall not be entitled to any per diem."}},{"id":"PH-H980-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Administrative powers and duties of the Board of Administrators. -The board of Administrators shall have the following powers and duties:\n(a) To prescribe, amend, modify, or repeal by-laws, rules and regulations, no inconsistent with the provisions of this Act, governing the manner in which the general business of the PHILCOA shall be exercised;\n(b) To fix the compensation of the officers and employees of the PHILCOA;\n(c) To approve the annual and/or such supplemental budgets of the PHILCOA which may be submitted to it by the management from time to time;\n(d) To carry on the business of the PHILCOA as provided by law; and\n(e) To perform such other duties as may be assigned to it by the President of the Philippines."}},{"id":"PH-H980-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Suspension and removal of Administrators. -Any member of the Board of Administration may, for cause, be suspended or removed by the President of the Philippines.\nManagement"}},{"id":"PH-H980-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"The management of the PHILCOA shall be vested in the Chairman of the Board of Administrators."}},{"id":"PH-H980-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Powers and duties of the Chairman of the Board. -The Chairman of the Board shall have the following powers and duties:\n(a) To direct and manage the affairs and business of the PHILCOA on behalf of the Board of Administrators and subject to its control and supervision;\n(b) To submit for approval within sixty days after the close of each fiscal year an annual report to the President of the Philippines and to each House of Congress, through the Board of Administrators;\n(c) To appoint and to fix the number with the approval of the Board of Administrators, of such subordinate officials and personnel as may be necessary for the proper discharge of the duties and functions of the PHILCOA, and, with the approval of the Board, to remove, suspend, or otherwise discipline, for just cause, any subordinate employee of the PHILCOA; and\n(d) To perform such other duties as may be assigned to him by the President of Administrators from time to time.\nAppointments and Promotions"}},{"id":"PH-H980-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Basis. -in the appointment and promotion of officers and employees, civil service eligibility, merit and efficiency shall serve as the basis. Any person appointed in violation of this prohibition shall be removed."}},{"id":"PH-H980-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Application of Civil Service Law and Regulations. -All officers and employees of the PHILCOA shall be subject to the Civil Service Law, rules and regulations, except those whose position may, upon recommendation of the Board of Administrators, be declared by the President of the Philippines as policy-determining, or highly technical in nature.\nCapitalization and Special Funds of the PHILCOA"}},{"id":"PH-H980-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Capitalization. -To raise the necessary funds to carry out the provisions of this Act and the purposes of the PHILCOA, there shall be levied a fee of ten centavos for every one hundred kilos of desiccated coconut, to be paid by the desiccating factory, coconut oil to be paid by the oil mills, and copra to be paid by the exporters, dealers or producers as the case may be. This service fee shall be collected by the PHILCOA under such rules and regulations that it shall promulgate: Provided, However, That pending the collection of service fee, the PHILCOA is hereby authorized to borrow from any banking institution the sum of fifty thousand pesos to be used in the organization and maintenance of this office."}},{"id":"PH-H980-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Special Fund. -The proceeds of the foregoing levy shall be set aside to constitute a special fund to be known as the \"Coconut Development Fund,\" which shall be available exclusively for the use of the PHILCOA. All the income and receipts derived from the special fund herein created shall accrue to, and form part of, the said fund to be available solely for the use of the PHILCOA.\nTransfer of Functions from other Offices"}},{"id":"PH-H980-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"The functions of the Bureau of Commerce under Commerce Administrative Order Numbered Two, Dated January sixteen, nineteen hundred and forty-eight, relating to the standardization and inspection of copra, and the functions of the Sugar Quota Office in the allocation of coconut oil exports under Executive Order Numbered Ninety-four, dated October fourth, nineteen hundred and forty-seven, are hereby transferred to the PHILCOA. The personnel in these offices in charge of carrying out the foregoing functions and who are duly qualified in the civil service shall be transferred to the PHILCOA and those who do not possess civil service eligibility shall be retired in accordance with existing laws and regulations.\nAudit"}},{"id":"PH-H980-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"The Audit General shall appoint a representative who shall be the Auditor of the PHILCOA. The number and salaries of the Auditor and such personnel as may be needed to assist him shall be determined by the Auditor General with the consent of the Board of Administrators. In case of disagreement, the matter shall be submitted to the President of the Philippines whose decision shall be final. Said salaries and other expenses of maintaining the Auditor’s office shall be paid by the PHILCOA.\nMiscellaneous Provisions"}},{"id":"PH-H980-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Applicability of the Corporation Law. -The provisions of the Corporation Law which are not inconsistent with the provisions of this Act, shall be applicable to the PHILCOA created thereunder."}},{"id":"PH-H980-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"No official employee of the Corporation shall directly or indirectly be financially interested in any contract with the corporation or in any special privilege granted by said Corporation during his term of office. Any violation of this prohibition shall be punished by dismissal from office and by a fine of not more than one thousand pesos or imprisonment of not more than one year, or both, at the discretion of the court."}},{"id":"PH-H980-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Repeal or modifications. -Republic Act Numbered Four hundred seventy-one providing for the transfer to the NACOCO of fifty per centum of the fees collected from the Copra Standardization and inspection Service is hereby repealed: Provided, That all amounts collected under said Act which are still unreleased upon approval hereof shall be turned over the PHILCOA. All acts, executive orders, administrative orders, and proclamations or parts thereof inconsistent with any of the provisions of this Act are likewise repealed or modified accordingly."}},{"id":"PH-H980-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Constitutionality. -If any provisions of this Act shall be held unconstitutional, the other provisions shall not thereby be affected."}},{"id":"PH-H980-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Effectivity. -This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Philippine Coconut Administration, Prescribing its Powers, Functions and Duties, and Providing for the Raising of the Necessary Funds for its Operation","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H981"] = {"id":"PH-H981","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1146_1954.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"授权政府按实际成本向稻米和玉米生产者及农民出售化肥，并指定农业与自然资源部为负责化肥销售与分配及执行本法各项规定的机构","en":"An Act Authorizing the Government to Sell Fertilizers to Rice and Corn Producers and Farmers at Actual Cost, Constituting the Department of Agriculture and Natural Resources, for This Purpose, as the Agency to Take Charge of the Sale and Distribution of Fertilizers and to Implement the Provisions of This Act","orig":"An Act Authorizing the Government to Sell Fertilizers to Rice and Corn Producers and Farmers at Actual Cost, Constituting the Department of Agriculture and Natural Resources, for This Purpose, as the Agency to Take Charge of the Sale and Distribution of Fertilizers and to Implement the Provisions of This Act"},"level":"law","status":"active","topics":["environment","culture"],"docNumber":"Republic Act No. 1146","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1146_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H981-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of policy. -It is hereby declared to be the national policy during the time that this act is in force to increase the production of rice and corn at a minimum cost of operation, this is to be made possible by the Government offering every possible encouragement and incentive to rice and corn producers and farmers and to utilize every possible means which will implement the rehabilitation and peace and order program of the Government."}},{"id":"PH-H981-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Government is hereby authorized to sell at actual cost fertilizers to palay and corn producers and farmers."}},{"id":"PH-H981-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Agriculture and Natural Resources is hereby designated to take charge of the sale and distribution of fertilizers, granting to the said department the power to promulgate rules and regulations subject to the provisions of this Act, and the authority to vest the powers and duties prescribed by this Act in any of its division or sections as it may deem wise."}},{"id":"PH-H981-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sum of six million pesos is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, as a revolving fund for the purchase and sale of fertilizers."}},{"id":"PH-H981-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Government to Sell Fertilizers to Rice and Corn Producers and Farmers at Actual Cost, Constituting the Department of Agriculture and Natural Resources, for This Purpose, as the Agency to Take Charge of the Sale and Distribution of Fertilizers and to Implement the Provisions of This Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H982"] = {"id":"PH-H982","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1147_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定每两年举行一次某些文官考试并为此授权拨款5万比索的法案","en":"An Act to Provide for the Holding of Certain Civil Service Examinations Once Every Two Years and Authorizing the Appropriations of Fifty Thousand Pesos Therefor","orig":"An Act to Provide for the Holding of Certain Civil Service Examinations Once Every Two Years and Authorizing the Appropriations of Fifty Thousand Pesos Therefor"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 1147","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1147_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H982-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Within one hundred twenty days from the date of release of the fund herein authorized to be appropriated and at least once every two years thereafter, the Bureau of Civil Service shall give first and second grade and regular and promotional junior teachers civil service examinations in the City of Manila and in such other places as the Commissioner of Civil Service may determine, the results of which shall be released within nine months from the date of each examination."}},{"id":"PH-H982-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of fifty thousand pesos is authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act. Thereafter, the necessary funds for the same purpose shall be provided in the annual General Appropriations Act."}},{"id":"PH-H982-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for the Holding of Certain Civil Service Examinations Once Every Two Years and Authorizing the Appropriations of Fifty Thousand Pesos Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H983"] = {"id":"PH-H983","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1148_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"对《国家国内税收法典》的修改","en":"An Act to Amend Section Twenty-Four of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended","orig":"An Act to Amend Section Twenty-Four of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1148","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1148_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H983-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty-four of Commonwealth Act Numbered Four hundred and sixty-six, as amended, is hereby further amended to read as follows:\n\"Sec. 24. Rate of tax on corporations. -There shall be levied, assessed, collected, and paid annually upon the total net income received in the preceding taxable year from all sources by every corporation organized in, or existing under the laws of the Philippines, no matter how created or organized, but not including duly registered general co-partnerships (compañias colectivas) a tax upon such income equal to the sum of the following:\n\"Twenty per centum upon the amount by which such total income does not exceed one hundred thousand pesos; and \"Twenty-eight per centum upon the amount by which such total net income exceeds one hundred thousand pesos; and a like tax shall be levied, assessed, collected, and paid annually upon the total from all sources within the Philippines by every corporation organized, authorized, or existing under the laws of any foreign country; Provided, However, That building and Loan Associations operating as such in accordance with sections one hundred and seventy-one to one hundred and ninety of the Corporation Law, as amended, as well as private educational institutions, shall pay a tax of twelve per centum and ten per centum, respectively, on their total net income: And Provided, further, That in the case of dividends received by a domestic or resident foreign corporation from a domestic corporation liable to tax under this Chapter or from a domestic corporation engaged in new and necessary industry, as defined under Republic Act Numbered Nine hundred and one, only twenty-five per centum thereof shall be returnable for purposes of the tax imposed by this section.\""}},{"id":"PH-H983-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The provisions of this Act shall apply to income received from January first, nineteen hundred and fifty-four."}},{"id":"PH-H983-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13"};
  FT["PH-H984"] = {"id":"PH-H984","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1149_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将大都会供水区债券债务上限由2000万比索提高至3000万比索，为此修订第2832号法第2条（m）项（经修正）的法案","en":"An Act Increasing the Limit of the Bonded Indebtedness of the Metropolitan Water District from Twenty Million Pesos to Thirty Million Pesos, Amending for the Purpose Subsection (m) of Section Two of Act Numbered Twenty-Eight Hundred Thirty-Two, as Amended","orig":"An Act Increasing the Limit of the Bonded Indebtedness of the Metropolitan Water District from Twenty Million Pesos to Thirty Million Pesos, Amending for the Purpose Subsection (m) of Section Two of Act Numbered Twenty-Eight Hundred Thirty-Two, as Amended"},"level":"law","status":"active","topics":["energy"],"docNumber":"Republic Act No. 1149","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1149_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H984-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subsection (m) of section two of Act Numbered Twenty-eight hundred thirty-two, as amended by Commonwealth Act Numbered Four hundred thirty-eight, is further amended to read as follows:\n\"(m) When essential to the proper administration of its corporate affairs or necessary for the proper transaction of its business or to carry indebtedness and issue bonds, it was organized, to construct indebtedness and issue bonds, subject to the approval of the Secretary of Finance. The bonded indebtedness of the District, of all classes, shall not at any time exceed thirty million pesos, and the issue thereof shall be subject to the conditions set forth in section five of this Act, as amended, and shall be limited to revenue-producing projects: Provided, That part of the amount borrowed shall be spent for sinking underground the water main pipes in Manila.\""}},{"id":"PH-H984-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Limit of the Bonded Indebtedness of the Metropolitan Water District from Twenty Million Pesos to Thirty Million Pesos, Amending for the Purpose Subsection (m) of Section Two of Act Numbered Twenty-Eight Hundred Thirty-Two, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H985"] = {"id":"PH-H985","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1150_1954.html","fetchedAt":"2026-10-06","articleCount":29,"structureMode":"ARTICLE","title":{"zh":"政府运营经费拨款法","en":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period from July First, Nineteen Hundred and Fifty-Four to June Thirtieth, Nineteen Hundred and Fifty-Five, and for Other Purposes","orig":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period from July First, Nineteen Hundred and Fifty-Four to June Thirtieth, Nineteen Hundred and Fifty-Five, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1150","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 29 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1150_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H985-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Appropriation of funds. -The following sums, or so much thereof as may be necessary, are appropriated out of any funds in the Philippine Treasury not otherwise appropriated for the operation of the Government of the Republic of the Philippines during the period from July first, nineteen hundred and fifty-four to June thirtieth nineteen hundred and fifty-five, except where otherwise specifically provided:\n[For the sake of brevity, the itemization under this Section of the funds appropriated for the operation of the Government had been deleted. Please refer to the unabridged version of the pertinent General Appropriations Act for the details.]\nGeneral Provisions"}},{"id":"PH-H985-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Authority to pay salaries not in conformity with the prescribed grades or rates of compensation. -Payment to incumbent employees of salaries the rates of which are not in conformity with the schedule of grades or rates of compensation provided in section three of Commonwealth Act Numbered Four hundred and two, as amended, is hereby authorized: Provided, That new appointments, whether original or promotional, to positions not carrying the salary rates prescribed in Commonwealth Act Numbered Four hundred and two, as amended, shall be made only at the rates authorized in the said Act."}},{"id":"PH-H985-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Authority to use savings in appropriations for \"salaries and wages,\" for \"sundry expenses,\" and for \"furniture and equipment\" to cover deficits. -Except as otherwise provided in this Act, any savings in the regular appropriations authorized in this Act for the Executive Departments for salaries and wages, for sundry expenses, and for furniture and equipment of the bureaus and offices under any Department, may, with the approval of the President, be used to cover a deficit in any other item of the regular appropriations, except for salaries and wages, under the same Department. Likewise, any savings in the appropriations for salaries and wages, for sundry expenses, and for furniture and equipment of any item under \"special purposes,\" may, with the approval of the President, be used to cover a deficit in any other item of appropriation, except for salaries and wages, under the same or other special purpose under the same Department. In no case, however, shall any item in the regular appropriations and appropriations for \"special purposes\" be augmented, pursuant to the authority granted in this section, by more than fifty per centum of the original appropriation provided in this Act for such item."}},{"id":"PH-H985-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Quarterly report to Congress on transfers of appropriations. -The Auditor General and the Commissioner of the Budget shall report separately to the Congress quarterly any transfers of appropriation made to cover a deficit, the report to specify the items and the amounts involved and in as many copies as there are members thereof."}},{"id":"PH-H985-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Authority to use savings for other purposes. -The President of the Philippines is authorized to use any savings in the appropriations authorized in this Act for the Executive Departments (1) for the payment of claims under section 699 of the Revised Administrative Code and the Workmen’s Compensation Act, whichever is applicable, to officers, employees and laborers who died or were injured in line of duty; (2) for the commutation of the money value of the additional leave, extended leave and accrued leave earned by American and deceased Filipino officers and employees, or by Filipino officers and employees separated from the service except for cause, for service rendered prior to November twenty-ninth, nineteen hundred and thirty-six; (3) for the purchase of furniture and equipment to replace those that may be lost through accident, fire or other calamity, or may have been damaged through the same cause, the disposal of which is deemed reasonable and necessary, if it would be more expensive to have them repaired, and for the purchase with the approval of the President of furniture and equipment to replace unserviceable ones condemned by the Auditor General; (4) for the payment of salaries of suspended employees who have subsequently been exonerated; (5) for the payment of the share of the National Government in the salaries of national officials in newly created cities and provinces where no appropriation has been provided therefor; (6) for the payment to the Government Service Insurance System of the three per cent contribution of the Government for the employees’ insurance premiums corresponding to the period from December thirty-first, nineteen hundred and forty-one to February twenty-eighth, nineteen hundred and forty-five, pursuant to section four of Republic Act Numbered One hundred thirty-two, the provisions of section 7(c) of Commonwealth Act Numbered One hundred eighty-six, as amended, to the contrary notwithstanding; (7) for the payment of commuted sick and vacation leaves of employees who may be retired under existing laws; (8) for the payment of additional compensation to government nurses assigned to public health nursing at ₱50 a month in lieu of quarters, subsistence and laundry allowances as provided under section three of Republic Act Numbered Six hundred forty-nine; (9) for the purchase or rental of accounting machines to carry out the plan of mechanizing the accounting system in the Government; (10) for the payment of premiums on insurance of government buildings and properties with the Property Insurance Fund in accordance with Republic Act Numbered Six hundred fifty-six; (11) for the payment of the obligation of the National Government under the provisions of subsection (a) under section 2553 of the Revised Administrative Code; (12) for the payment of the cash commutation of the accumulated vacation and sick leave of employees separated from the service, in accordance with the provisions of Republic Act Numbered Six hundred eleven; (13) for the payment of expenses for printing of briefs in cases appealed by the Government; (14) for gratuity of employees whose positions are abolished or who are retired; (15) for the improvement of food rations in government hospitals and leprosaria; (16) for rural improvement; and (17) for payment to the Bureau of Prisons for its normal operation."}},{"id":"PH-H985-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Suspension of expenditure of appropriations. -Except as otherwise provided in this Act and whenever in his judgment the public interest so requires, the President is authorized to suspend or otherwise stop the expenditure of any amount herein appropriated in any item or items for the Executive Departments for any purpose, except those for salaries of positions with incumbents, and thereupon the funds affected by such action shall become available for any other expenditures authorized in this Act for the Executive Departments as the President may determine, except for salaries and wages. In no case, however, shall any item of appropriation be augmented, pursuant to the authority granted in this section, by more than fifty per centum of the original appropriation provided in this Act for such item. The Auditor General and the Commissioner of the Budget shall report separately to the Congress within a period of thirty days any suspension or transfer of funds made by the President during the previous quarter."}},{"id":"PH-H985-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Provision for \"excess of actual salary.\"— The item of appropriation for \"excess of actual salary\" provided in this Act under \"salaries and wages\" shall be paid to the incumbent of the position to which said \"excess\" pertains who is actually receiving the same \"excess\" as part of the salary granted to him upon his appointment to the said position before the reduction of the basic pay thereof to the amount provided herein: Provided, However, That if the position be vacated and the successor to its previous incumbent shall have previously received an equal salary plus the \"excess of actual salary\" in the same or any other branch of the government service, such excess shall be allowable to him."}},{"id":"PH-H985-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Allotment of funds to cover authorized appropriations.—\na. No appropriation to any bureau, office or agency shall become available for expenditure until such bureau, office or agency shall have submitted to the Commissioner of the Budget a request for allotment of funds, such request for allotment to consist of an estimate of the amount required for each activity and each purpose for which money is to be expended during the applicable allotment period, and until such estimate contained in the said request for allotment shall have been approved, increased or decreased by the Commissioner of the Budget and funds allotted therefor as hereinafter provided. The form of the said request for allotment shall be prescribed by the Commissioner of the Budget and shall be submitted to him at least 25 days prior to the beginning of the first allotment period.\nb. For purposes of the administration of the allotment system herein provided, each fiscal year shall be divided into four quarterly allotment periods beginning, respectively, on the first day of July, October, January and April: Provided, That in any case where the quarterly allotment period is impracticable, the Commissioner of the Budget may prescribe a different period suited to the circumstances but not extending beyond the end of the fiscal year.\nc. Each request for allotment shall be reviewed by the Commissioner of the Budget and the respective amounts therein shall be allotted for expenditures, provided the estimate therein is within the terms of the appropriations as to amount and purpose, having due regard for the probable future needs of the bureau, office or agency for the remainder of the fiscal year or other term for which the appropriation was made, and provided the bureau, office or agency contemplates expenditure of the allotment during the period. Otherwise, the said Commissioner of the Budget shall act promptly upon all requests for allotment and terms of the appropriation and the prospective needs of the bureau, office or agency, and shall reduce the amount to be allotted accordingly. The Commissioner of the Budget shall act promptly upon all requests for allotment and shall notify every bureau, office or agency of its allotments at least 5 days before the beginning of each allotment period. The total amount allotted to any bureau, office or agency for the fiscal year or other term for which the appropriation was made shall not exceed the amount appropriated for said year or term.\nd. The Commissioner of the Budget shall also have authority at any time to modify or amend any allotment previously made by him.\ne. In case the Commissioner of the Budget shall discover at any time that the probable receipts from taxes or other sources for any fund will be less than were anticipated and that as a consequence the amount available for the remainder of the term of the appropriation, or for any allotment period will be less than the amount estimated or allotted therefor, he shall, with the approval of the President, and after notice to the bureau, office or agency concerned, reduce the amount or amounts allotted, or to be allotted, so as to prevent a deficit.\nf. The Commissioner of the Budget shall promptly transmit records of all allotments and modifications thereof to the Auditor General, the Chairman of the Committee on Finance of the Senate and the Chairman of the Committee on Appropriations of the House of Representatives.\ng. The Commissioner of the Budget shall maintain records showing at all times by funds, accounts, and other pertinent classifications for the amounts appropriated, the estimated revenues, the actual revenues or receipts, the amounts allotted and available for expenditures, the unliquidated obligations, actual balances on hand, and the unencumbered balances of the allotments for each bureau, office or agency.\nh. No payment shall be made and no obligation shall be incurred against any fund, allotment or appropriation unless the accounting officers of the Budget Commission shall first certify that there is a sufficient unencumbered balance in such fund, allotment or appropriation, after taking into consideration all previous expenditures and outstanding obligations, to meet the same.\ni. Every expenditure or obligation authorized or incurred in violation of the provisions of this Act shall be void. Every payment made in violation of the provisions of this Act shall be illegal, and every official authorizing or making such payment, or taking part therein, and every person receiving such payment, or any part thereof, shall be jointly and severally liable to the Government for the full amount so paid or received. If any officer or employee of the Government shall knowingly incur any obligation or shall authorize or make any expenditure in violation of the provisions of this Act, or take part therein, it shall be ground for his removal by the officer appointing him, and if the appointing officer be other than the President and shall fail to remove such officer or employee, the President shall exercise such power of removal after giving notice of the charges and opportunity for hearing thereon to the accused officer or employee and to the officer appointing him.\nj. Since the effective operation of the allotment system with respect to the appropriations authorized in this Act is affected by the appropriations authorized in other acts, the provisions of this section relating to the allotments system are hereby made expressly applicable to other appropriations and funds of all kinds, including standing or continuing appropriations, and special trust and other funds; but the provisions hereof relating to the allotment system shall not apply to appropriations for the Congress of the Philippines, Supreme Court, Court of Appeals, Courts of First Instance and Justice of the Peace Courts nor to appropriations or any other monies made available for the General Auditing Office and the Commission on Elections."}},{"id":"PH-H985-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Creation of appropriation reserves. -The chiefs of bureaus and offices shall establish reserves of not less than five per centum of the total appropriation of their respective bureaus and offices to provide for contingencies and emergencies which would otherwise require a deficiency appropriation. All or a portion of an appropriation may be reserved when it is determined that the amounts involved may not be needed. Should conditions change during the fiscal year which would justify the use of the reserve, the necessary adjustment may be made by the Commissioner of the Budget when requested by the bureau or office affected."}},{"id":"PH-H985-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Purchase of locally manufactured furniture, equipment, parts, accessories, supplies and materials. -All appropriations for the purchase of furniture, equipment, supplies and materials authorized in this Act shall be available only for locally manufactured furniture, equipment, parts, accessories, supplies and materials, except when none is available in the market, or when the prices of the locally manufactured article exceed those determined by the Flag Law by ten per cent."}},{"id":"PH-H985-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Renting of automobiles, jitneys or trucks for a continuous period exceeding fifteen days prohibited. -No appropriation provided in this Act for the Executive Departments shall be used for renting automobiles, jitneys or trucks on the monthly basis nor on the daily basis for a continuous period exceeding fifteen days."}},{"id":"PH-H985-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Authority to purchase motor vehicles. -No appropriation authorized in this Act shall be used for the purchase of automobiles, jitneys, jeeps, station wagons, motorcycles and other motor vehicles unless otherwise specifically provided in this Act."}},{"id":"PH-H985-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Officials entitled to government motor transportation. -The following officials are entitled to use government motor transportation chargeable against the appropriations authorized in this Act:\n(1) The President of the Philippines,\n(2) The Vice-President of the Philippines,\n(3) The President of the Senate,\n(4) The Speaker of the House of Representatives,\n(5) The President Pro-Tempore of the Senate,\n(6) The Majority Floor Leader of the Senate,\n(7) The Chairman, Committee on Finance, of the Senate,\n(8) The Chairman, Committee on Accounts, of the Senate,\n(9) The Chairman, Committee on Foreign Relations, of the Senate,\n(10) The Chairman, Committee on Public Works, of the Senate,\n(11) The Minority Floor Leader of the Senate,\n(12) The Secretary of the Senate,\n(13) The Speaker Pro-Tempore of the House of Representative,\n(14) The Majority Floor Leader of the House of Representatives,\n(15) The Chairman, Committee on Appropriations, of the House of Representatives,\n(16) The Chairman, Committee on Accounts, of the House of Representatives,\n(17) The Chairman, Committee on Foreign Affairs, of the House of Representatives,\n(18) The Chairman, Committee on Public Works, of the House of Representatives,\n(19) The Minority Floor Leader of the House of Representatives,\n(20) The Secretary of the House of Representatives,\n(21) The Chief Justice of the Supreme Court,\n(22) The Presiding Justice of the Court of Appeals,\n(23) The Auditor General,\n(24) The Ambassadors, Ministers Plenipotentiary and Consuls in charge of consulates while in their respective stations abroad, and\n(25) The Chief of Staff and the Vice-Chief of Staff and the Commanding Officers of the other Major Services of the Armed Forces of the Philippines."}},{"id":"PH-H985-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Officials entitled to transportation allowance. -The Department Heads, including the Administrator of Economic Coordination, the Commissioner of the Budget, the Chairman of the Commission on Elections, and the Social Welfare Administrator are hereby granted a commutable transportation allowance of two hundred fifty pesos each per month; the Undersecretaries of Departments and officials with the same rank, the Public Service Commissioner, the Legislative Secretary, the Legislative Liaison Officer, and the Presiding Judge of the Court of Industrial Relations, two hundred pesos each per month; and the following Directors or chiefs of bureaus and offices, and the Sergeant At Arms of the House of Representatives, one hundred pesos each per month, chargeable against the appropriations authorized in this Act for their respective offices:\n(1) The Director of Printing,\n(2) The Commissioner of Civil Service,\n(3) The Commissioner of Customs,\n(4) The Collector of Internal Revenue,\n(5) The Treasurer of the Philippines,\n(6) The Purchasing Agent, Bureau of Supply,\n(7) The Insurance Commissioner,\n(8) The Chief, General Land Registration Office,\n(9) The Director, National Bureau of Investigation,\n(10) The Commissioner of Immigration,\n(11) The Director of Prisons,\n(12) The Chairman, Code Commission,\n(13) The Director of Plant Industry,\n(14) The Director of Animal Industry,\n(15) The Director of Forestry,\n(16) The Director of Lands,\n(17) The Director of Mines,\n(18) The Director of Fisheries,\n(19) The Director of Soil Conservation,\n(20) The Director of Agricultural Extension,\n(21) The Manager, Fiber Inspection Service,\n(22) The Director of Public Works,\n(23) The Director of Posts,\n(24) The Director of Telecommunications,\n(25) The Chief, Motor Vehicles Office,\n(26) The Director of Public Schools,\n(27) The Director of Public Libraries,\n(28) The Director, Institute of National Language,\n(29) The Director of National Museum,\n(30) The Director of Private Schools,\n(31) The Director of Labor,\n(32) The Commissioner, National Employment Service,\n(33) The Commissioner, Workmen’s Compensation Commission,\n(34) The Chief, Wage Administration Service,\n(35) The Captain (Director), Bureau of Coast and Geodetic Survey,\n(36) The Chairman, Philippine Veterans Board,\n(37) The Chairman, Board on Pensions for Veterans,\n(38) The Director of Quarantine,\n(39) The Director of Hospitals,\n(40) The Director of Health,\n(41) The Director of Commerce,\n(42) The Administrator, Sugar Quota Administration,\n(43) The Director, Patent Office,\n(44) The Commissioner, Securities and Exchange Commission,\n(45) The Administrator, Civil Aeronautics Administration,\n(46) The Director, Weather Bureau,\n(47) The Director of the Census and Statistics,\n(48) The Administrator, Cooperatives Administration Office,\n(49) The Director, Institute of Science and Technology,\n(50) The Director, Philippine General Hospital, and\n(51) The Counselors in the Department of Foreign Affairs."}},{"id":"PH-H985-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Bureaus and offices entitled to use, operate and maintain government motor vehicles and launches. -No bureau or office shall use, operate or maintain from the appropriations authorized in this Act government service cars, jeeps, station wagons, vans, service trucks, pick-up trucks, launches, speedboats, motorcycles, etc., except the following:\n(1) The House of Representatives, for general service purposes;\n(2) The Senate, for general service purposes;\n(3) The Malacañang Household, for general service purposes;\n(4) The National Intelligence Coordinating Agency, in the coordination of the national intelligence activities and in carrying out its functions in the interest of national security;\n(5) The Radio Station DZFM, for covering special events for delayed broadcasts, servicing of sponsored programs, contacting artists, fetching \"sign on\" personnel and conducting home those \"signing off;\"\n(6) The Social Welfare Administration, for ministering relief, during military actions against dissidents, to evacuees, the injured and incapacitated and to the victims of typhoons, earthquakes, fires, floods, tidal waves and volcanic eruptions; and for conducting the inmates of Welfareville to and from the Courts, hospitals and other offices, procuring materials and food supplies for their subsistence, and delivering food to the various units within the Welfareville compound, including collection and disposal of garbage;\n(7) The Budget Commission, for the gathering from the various government offices and instrumentalities of such data and information as are essentially material or pertinent to the exercise of authority over budget operations and control, for the performance of duties connected with the preparation of the National Budget, and for wage and position classification survey;\n(8) The Bureau of Printing, for the delivery and/or shipment of printed matters, books and/or forms to various offices;\n(9) The Department of Foreign Affairs, for carrying out protocol duties in connection with the arrival or visit in the Philippines of high dignitaries and officials or accredited representatives of foreign governments, and for the delivery of diplomatic pouches to and from points of embarkation or shipment;\n(10) The Bureau of Customs, for use of examiners of the Appraisers Division in the inspection of bonded warehouses, including embroidery factories, for hauling parcels from the Bureau of Posts to the Customs Building for examination and for carrying out the so-called \"immediate payment system\" under which the Division will dispatch in a motor vehicle import entries for examination to its supervisors stationed at the piers for distribution to the examiners detailed under them and have the examined entries and the examiners’ samples brought to the Customs Building, and for carrying out detective and police duties of the Port Patrol Division in Manila and of the patrol service in the Port of Cebu;\n(11) The Bureau of Internal Revenue, for the strict enforcement of the internal revenue laws and regulations and detection of violations thereof;\n(12) The Philippine Council for United States Aid (PHILCUSA), for use in inspecting projects being undertaken by the Government jointly with the Foreign Operations Administration (FOA) and in gathering and transmitting data and information necessary for the efficient supervision and coordination of the activities of said projects;\n(13) The Bureau of the Treasury, for transportation of cash from the Central Bank of the Philippines to the Bureau of the Treasury, and vice versa;\n(14) The National Bureau of Investigation, for detection and investigation of crimes and criminals and other law violations;\n(15) The Bureau of Prisons, for conducting prisoners to and from the Bureau of Prisons, inspection of prison institutions and stations, procuring food supplies and materials, and delivering products and/or manufactures of the Prison Industries in Muntinlupa and in the penal colonies;\n(16) The Bureau of Fisheries, for the collection of marine specimens, inspection of experimental fish farms and distribution of seedlings;\n(17) The Bureau of Plant Industry, for the control of abaca mosaic and other plant pests and diseases, including demonstration and extension work;\n(18) The Bureau of Forestry, for the distribution of seedlings and transportation of supplies and materials and cinchona barks to ports of shipment;\n(19) The Bureau of Animal Industry, for the distribution of animal products and transportation of animals and feeds, including insemination work;\n(20) The Bureau of Agricultural Extension, for carrying out its extension work and diffusing among the people, particularly those in rural areas, useful and practical information on agriculture, soil conservation, livestock, fisheries, forest conservation, public lands and natural resources laws, home economics and rural life by means of field demonstrations, lectures, conferences, publications and other means of disseminating information;\n(21) The Bureau of Public Works, for undertaking the construction of public works projects, inspection and supervision thereof, and for the procurement of construction supplies and materials;\n(22) The Bureau of Posts, for the transportation of strictly mail matters;\n(23) The Bureau of Telecommunications, for the construction, repair, transfer and maintenance of telegraph, telephone and radio stations and circuits and the delivery of telegrams and radiograms;\n(24) The Motor Vehicles Office, for the enforcement of the provisions of the Motor Vehicle Law;\n(25) The vocational schools, for instructional purposes requiring the use, demonstration and/or operation of motor or other powered vehicles;\n(26) The Armed Forces of the Philippines, when on military operations or on active duty in the restoration and maintenance of peace and order;\n(27) The Department of Health, for the use of the Division of Tuberculosis in BCG Vaccination and Traveling X-ray Examination Units, the Division of Health Education and Information in exhibiting health films and dissemination of health information in rural areas, and the Public Health Research Laboratories in connection with health research, including the distribution of vaccines, sera and other biological preparations;\n(28) Government hospitals, for ambulance service and procuring food supplies and materials for the subsistence of patients and personnel entitled thereto;\n(29) The Bureau of Health, for health, sanitation and prevention and control of epidemics;\n(30) The Bureau of Quarantine, whenever used by quarantine officers exclusively for quarantine work;\n(31) The Civil Aeronautics Administration, for the operation and maintenance of its landing fields, including supervision and reconstruction or repair of signaling equipment located thereat;\n(32) The Bureau of Coast and Geodetic Survey, for carrying out field reconnaissance, triangulations, precise leveling and magnetic and gravity measurements, and for ship servicing;\n(33) The Weather Bureau, for the maintenance, operation and inspection of its meteorological stations, including the Manila International Airport Forecasting Center and the Diliman Geophysical and Astronomical Station, and delivery of supplies thereto;\n(34) The General Auditing Office, for the inspection of the delivery of equipment and supplies and materials to the various bureaus and offices of the Government, as well as to sites of public works construction, and for surprise examinations of disbursing officers;\n(35) The Bureau of Mines, for the transportation of mineral samples to and from the office for the geological, mineralogical and mineral land survey parties operating in the different parts of the Philippines;\n(36) The Fiber Inspection Service, for carrying out its work of inspection and supervision of fiber grading-baling establishments, fiber improvement and demonstration work;\n(37) The Institute of Science and Technology, for visit and inspection of factories, for the collection of forest, plant, animal and marine by-products and agricultural wastes for use in research and laboratory investigations, including survey of sources of raw materials in different regions;\n(38) The Office of Economic Coordination, for use in inspecting projects being undertaken by government corporations, including private industrial establishments applying for tax exemption under Republic Act Numbered Thirty-five, and in gathering and transmitting data and information necessary for the efficient supervision and coordination of the activities of the said corporations;\n(39) The Wage Administration Service, for use by regional wage inspection supervisors in supervising the enforcement of the Minimum Wage Law, in the inspection of agricultural, industrial and commercial establishments, especially in out-of-the-way locations, and in making special investigations and economic surveys necessary for the administration and enforcement of the law; and\n(40) The Commission of Volcanology, for inspecting and observing volcanoes and warning people in danger areas."}},{"id":"PH-H985-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Proper use of government motor vehicles. -The use of government motor vehicles by bureaus and offices for the purposes enumerated in section fifteen hereof shall be authorized only through the issuance for each trip of a serially numbered ticket, duly signed by the chief or the administrative officer of the bureau or office concerned. These motor vehicles shall be used strictly for official business, bear government plates only and after office hours kept in the garage provided therefor by the bureau or office to which they belong, except when in use for strictly official business outside office hours."}},{"id":"PH-H985-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Use of more than one motor vehicle prohibited. -With the exception of the President, no government official or employee authorized to use any vehicle operated and maintained from the funds appropriated in this Act shall be allowed to use more than one such motor vehicle: Provided, However, That the Vice-President, the President of the Senate, and the Speaker of the House of Representatives may be allowed to use two motor vehicles each: And Provided, finally, That no official who has been furnished motor transportation by any government corporation shall be allowed to use motor vehicle transportation operated and maintained from funds appropriated in this Act.\nThe Auditor General is hereby empowered to issue rules and regulations for the proper implementation and enforcement of the provisions of this section and sections 14, 15 and 16."}},{"id":"PH-H985-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Disposition of motor vehicles not used by a bureau or office. -All motor vehicles owned by or assigned to the different departments, bureaus, offices and branches of the National Government not needed by the officials and for the purposes enumerated in sections thirteen and fifteen of this Act shall be disposed of to the highest bidder at public auction sales announced in newspapers of general circulation at least ten days before the sale: Provided, That the former user thereof shall be given preference if he offers and pays a price equal to that of the highest bid by others."}},{"id":"PH-H985-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Prohibition against the use of appropriations for the payment of salaries and wages of officers or employees engaged in a strike against the Government. -Subject to existing civil service rules and regulations and the proper administrative proceedings, no part of the funds of, or available for expenditure by, any agency included in this Act shall be used to pay the salary or wages of any officer or employee who engages in a strike against the Government of the Republic of the Philippines or who is a member of an organization of government employees that in the opinion of the Secretary of Justice asserts the right to strike against the Government of the Republic of the Philippines, or who in the opinion of said Secretary of Justice advocates, or is a member of an organization that advocates, the overthrow of the Government of the Republic of the Philippines by force or violence: Provided, That for the purposes hereof an affidavit shall be considered sufficient evidence that the person making the affidavit has not, contrary to the provisions of this section, engaged in a strike against the Government of the Republic of the Philippines, is not a member of any organization of government employees that asserts the right to strike against the Government of the Republic of the Philippines, or that such person does not advocate, and is not a member of an organization that advocates, the overthrow of the Government of the Republic of the Philippines by force or violence."}},{"id":"PH-H985-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Per diems outside of the Philippines. -No per diems in excess of fifty pesos shall be paid to any official or employee traveling outside of the Philippines."}},{"id":"PH-H985-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"No transfer of salary savings to the Government Service Insurance System. -The provisions of Republic Act No. 660 to the contrary notwithstanding, no savings from salaries and wages under the general fund and the special, revolving, trust, depository and other funds shall be transferred to the Government Service Insurance System."}},{"id":"PH-H985-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Reinsurance of government buildings to be equitably distributed among private insurance companies in the Philippines. -In all cases where appropriations are provided in this Act for payment of premiums covering the insurance of government buildings with the Property Insurance Fund, reinsurance shall be equitably distributed among private insurance companies doing business in the Philippines on uniform terms, conditions and rates of premiums."}},{"id":"PH-H985-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Prohibition against the transfer of appropriations of the Department of National Defense. -The provisions of section 6 of this Act to the contrary notwithstanding, no amount appropriated for the Department of National Defense shall be transferred to any other Executive Department."}},{"id":"PH-H985-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Use of savings from abolished positions for standardizing salaries. -Any vacant position in any bureau or office in any Executive Department may be abolished and the savings resulting therefrom shall be available for standardizing under the provisions of Commonwealth Act Numbered Four hundred two, as amended, the salaries of other positions in any bureau or office within the same Executive Department: PROVIDED, That the maximum salary may be fixed at seven thousand two hundred pesos per annum, the provisions of the said Commonwealth Act, as amended, to the contrary notwithstanding."}},{"id":"PH-H985-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Authority to harmonize the appropriation structure with the new terminology of classification of accounts prescribed in Auditor General Circular No. 29. -The Commissioner of the Budget is hereby authorized to harmonize the appropriation structure with the new terminology of classification of accounts prescribed in Auditor General Circular No. 29: PROVIDED, That such reclassification shall not increase or decrease the aggregate sum appropriated in this Act for the various objects affected under each Department, bureau or office."}},{"id":"PH-H985-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"The Committee on Finance of the Senate and the Committee on Appropriations of the House of Representatives to look into all matters relating to public expenditures. -The Committee on Finance of the Senate and the Committee on Appropriations of the House of Representatives are hereby authorized to look at any time into all matters relating to funds for the expenditures of the National Government and for the payment of public indebtedness; auditing of accounts and expenditures of the National Government; claims against the Government; and in general all matters relating to public expenditures."}},{"id":"PH-H985-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Expenditure and disbursement of special funds. -No expenditure shall be incurred, nor any disbursement made, out of the appropriations authorized in this Act from special, revolving and trust funds and from receipts automatically appropriated which will exceed at any one time either the fund itself or the cash in the National Treasury pertaining to such fund."}},{"id":"PH-H985-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Appropriations chargeable against the Philippine Charity Sweepstakes Fund. -The appropriations provided in this Act for carrying out the activities heretofore financed from the receipts of the Philippine Charity Sweepstakes Fund shall continue to be charged against the said Fund, and the Board of Directors of the Philippine Charity Sweepstakes shall allot the amounts thereof in the distribution of the Philippine Charity Sweepstakes Fund."}},{"id":"PH-H985-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Effective date. -This Act shall take effect on July first, nineteen hundred and fifty-four, except where otherwise stated.\nApproved: June 17, 1954."}}],"pack":"ph-p13"};
  FT["PH-H986"] = {"id":"PH-H986","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1151_1954.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"设立土地登记委员会","en":"An Act Creating the Land Registration Commission, and Authorizing and Appropriating the Necessary Funds Therefor","orig":"An Act Creating the Land Registration Commission, and Authorizing and Appropriating the Necessary Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1151","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1151_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H986-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Land Registration Commission. -In order to have a more efficient execution of the existing laws relative to the registration of lands, there is created a commission to be known as the Land Registration Commission, under the executive supervision of the Secretary of Justice. Said Commission shall have supervision and control over all Registers of Deeds, as well as the clerical and archival system of the Courts of First Instance throughout the Philippines in the exercise of the duties and functions conferred upon them with the reference to the registration of lands, and shall constitute a central repository of original records in matters connected with land titles and the registration thereof.\""}},{"id":"PH-H986-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Chief and Assistant Chief of the Commission. -The Land Registration Commission shall have a chief and an assistant chief, to be known, respectively, as the Commissioner and the Assistant Commissioner of Land Registration who shall be appointed by the President with the consent of the Commission on Appointments. The Commissioner shall be a duly qualified member of the Philippine Bar with at least five years of practice in the legal profession, and shall be entitled to the same compensation, emoluments and privileges as those of a Judge of the Court of First Instance. The Assistant Commissioner, who shall possess the same qualifications as those required of the Commissioner, shall receive compensation at the rate of seven thousand two hundred pesos per annum. He shall act as Commissioner of Land Registration during the absence or disability of the Commissioner, and when there is a vacancy in the position until another person shall have been designated or appointed in accordance with law. The Assistant Commissioner shall also perform such other functions as the Commissioner may assign to him."}},{"id":"PH-H986-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"General functions of the Commission. -The Commissioner of land Registration shall take over all the powers and functions as are now conferred upon the Chief of the General Land Registration Office, which positions is hereby abolished, as well as the powers and functions of the Judge of the Fourth Branch of the Court of First Instance of Manila, in all matters heretofore submitted to it for resolution under section two hundred of the Administrative Code. The Commissioner shall likewise exercise executive supervision over all the personnel of the Courts of First Instance throughout the Philippines with respect to the discharge of duties and functions conferred by law upon such personnel in relation to registration of lands, and all clerks of said courts acting with respect to the same shall be deemed to be under the Commissioner. It shall be the duty of said clerks of court to attend, either in person or by deputy, all sessions of their respective courts wherein proceedings relative to registration of lands are held, to keep minutes of such proceedings, and to perform with reference thereto all the duties and functions of clerks of court. The Commissioner of Land Registration shall designate an officer under him to act as clerk of the fourth branch of the Court of First Instance of Manila in matters relating to the registration of land and perform in connection therewith all the duties and functions of clerk of court.\nThe Commissioner of Land Registration shall see to it shall all orders, decisions, and decrees promulgated relative to the registration of lands are properly attended to and given due course, for which purpose he shall issue all needful rules and regulations, subject to the approval of the Secretary of Justice."}},{"id":"PH-H986-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Reference of doubtful matters to Commissioner of Land Registration. -When the Register of Deeds is in doubt with regard to the proper step to be taken or memorandum to be made in pursuance of any deed, mortgage, or other instrument presented to him for registration, or where any party in interest does not agree with the Register of Deeds with reference to any such matter, the question shall be submitted to the Commissioner of Land Registration either upon the certification of the Register of Deeds, stating the question upon which he is in doubt, or upon the suggestion in writing by the party in interest; and thereupon the Commissioner, after consideration of the matter shown by the records certified to him, and in case of registered lands, after notice to the parties and hearing, shall enter an order prescribing the step to be taken or memorandum to be made. His decision in such cases shall be conclusive and binding upon all Registers of Deeds: Provided, However , That when a party in interest disagrees with the ruling or resolution of the Commissioner and the issue involves a question of law, said decision may be appealed to the Supreme Court within thirty days from and after receipt of the notice thereof."}},{"id":"PH-H986-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Transfer of functions, records, personnel, appropriation and properties. -All the functions, records, personnel, equipment, unexpended appropriations and other properties of the General Land Registration Office are hereby transferred to the Land Registration Commission."}},{"id":"PH-H986-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Repealing Clause. -All existing laws or parts thereof as may be inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H986-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The sum of two million pesos, or so much thereof as may be necessary, is hereby authorized and appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purposes of this Act, for the fiscal year ending June thirty, nineteen hundred and fifty-five, broken down as follows:\nSalaries and Wages ₱1,542,040.00 Sundry expenses 226,960.00 Furniture and equipment 231,000.00 The same sum or so much thereof as may be necessary shall be included yearly in the appropriation acts for subsequent fiscal years."}},{"id":"PH-H986-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13"};
  FT["PH-H987"] = {"id":"PH-H987","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1152_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of One Million One Hundred Eleven Thousand Seven Hundred Forty-Two Pesos for the Maintenance and Operation of Six Patrol Gunboats Medium Programmed for Delivery by the United States Government to the Philippine Government During the Year Nineteen Hundred and Fifty-Four","orig":"An Act Appropriating the Sum of One Million One Hundred Eleven Thousand Seven Hundred Forty-Two Pesos for the Maintenance and Operation of Six Patrol Gunboats Medium Programmed for Delivery by the United States Government to the Philippine Government During the Year Nineteen Hundred and Fifty-Four"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1152","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1152_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H987-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated out of any funds in the Philippine Treasury not otherwise appropriated an additional sum of one million one hundred eleven thousand seven hundred forty-two pesos for the Philippine Navy for the maintenance and operation of six patrol gunboats medium programmed for delivery by the United States Government to the Philippine Government during the year nineteen hundred fifty-four, as hereinafter specified:\nSalaries and Wages\n1. Pay and allowances of officers and enlisted men; base pay, sea duty pay at ten per cent of base pay; rental and commutations of quarters, and commutations and/or subsistence allowance of officers andenlisted men; longevity pay for officers, additional pay for specialists under section eighty-nine of the National Defense Act, as amended; re-enlistment bonus, and clothing allowance of enlisted men: Provided, That the basic subsistence allowance shall be paid at the rate of one peso each per day and the additional subsistence shall be paid when on sea duty at the rate of two pesos daily for each officer, one peso for each enlisted man: Provided, further, That officer-patients and enlisted men-patients when confined in hospitals and dispensaries shall be paid their subsistence allowance at the rate of two pesos each per day; And, Provided, finally, That the Minimum Wage Law shall be implemented through the grant of salary differential to increase the total compensation of apprentice seamen the one thousand four hundred and forty pesos per annum, seamen second class to one thousand four hundred and seventy pesos per annum and seamen first class to one thousand five hundred pesos per annum ₱469,568.00 Sundry Express\n2. Consumption of supplies and materials peculiar to naval operations, to include quartermaster, ordinance, engineering, medical, dental, signal, general stores, fuel, water, lubricants, grease and ship supplies: Provided, That Philippine Navy watercrafts shall be used only by military personnel and their immediate dependents, and by government officials and employees on official business: Provided, further, That all other persons including guests of such military personnel and their dependents using Philippine Navy watercraft shall pay for such use before the trip at the rate charged by commercial steamship lines: And Provided, finally, That the limitations herein provided shall not apply to the trips of any organization or agency to extend relief in cases of disasters or calamities ₱540,174.00\n3. For the drydocking and repairs of six patrol gunboats medium 102,000.00 Total ₱1,111,742.00"}},{"id":"PH-H987-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any portion of the appropriation herein appropriated remaining unexpended after June thirty, nine-hundred fifty five shall revert to the unappropriated surplus in the National Treasury, and the fund necessary to maintain and operate the aforementioned six patrol gunboats medium in succeeding fiscal years shall be included in the General Appropriation Acts for said fiscal years."}},{"id":"PH-H987-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13"};
  FT["PH-H988"] = {"id":"PH-H988","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1153_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订1909年《菲律宾关税法》第8条第22款的法案","en":"An Act to Amend Paragraph Twenty-Two of Section Eight of the Philippine Tariff Act of Nineteen Hundred and Nine","orig":"An Act to Amend Paragraph Twenty-Two of Section Eight of the Philippine Tariff Act of Nineteen Hundred and Nine"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 1153","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1153_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H988-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph twenty-two of section eight of the Philippine Tariff Act of Nineteen hundred and nine is amended to read as follows:\n\"22. (a) Tars, pitches, and tar oils, not otherwise provided for; mineral oils, crude or refined (except gasoline, naphtha, and other similar products or distillation), including those illumination, lubrication fuel, or solvents, vaseline (except when compounded with other substances); axle grease of all kinds; asphaltums; carbolineum and similar compounds; gross weight, one hundred kilos, twenty five cents.\n\"(b) Gasoline, naphtha, and other similar products of distillation, gross weight, one hundred kilos, fifty cents.\n\" Provided, That no article classified under clause (a) of this paragraph shall pay a less rate of duty then ten per centum, ad valorem.\n\" Provided, finally, That though imported under a name referable to clause (a) of this paragraph, paraffin, or other similar products, shall be classified under paragraph eighty-three of this Act.\""}},{"id":"PH-H988-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Paragraph Twenty-Two of Section Eight of the Philippine Tariff Act of Nineteen Hundred and Nine","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
