  FT["PH-H992"] = {"id":"PH-H992","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1157_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第920号共和国法第一编E部分（a）目拉乌尼翁省若干项目的法案","en":"An Act to Amend Certain Items for the Province of La Union Subsection (a), Title E, Section One Republic Act Numbered Nine Hundred Twenty","orig":"An Act to Amend Certain Items for the Province of La Union Subsection (a), Title E, Section One Republic Act Numbered Nine Hundred Twenty"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 1157","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1157_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H992-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Items (d) and (e) of Group I and items (f), (g) and (i) of Group II for the province of La Union, subsection (a), Title E, section one, Republic Act Numbered Nine hundred twenty, are amended to read as follows:\n\"(d) For the construction of an artesian well, including an elevated take in the poblacion of San Juan ₱10,000.00 \"(e) For the construction of the communal irrigation system in the barrio of Cabaroan, Bacnota 10,000.00 \"(f) For the construction of the communal irrigation system in the barrio of Cadacian, San Fernand 6,000.00 \"(f-1) For the repair of the communal irrigation system in the barrio of Tanquigan, San Fernand 1,000.00 \"(g) For the repair and improvement of the Bangar-Sengat Castro road, in Bangar and Sudipe 5,000.00 \"(i) For the construction of the communal irrigations system in the barrio of Guinabang, Bacnota 26,000.00"}},{"id":"PH-H992-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Items for the Province of La Union Subsection (a), Title E, Section One Republic Act Numbered Nine Hundred Twenty","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H993"] = {"id":"PH-H993","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1158_1954.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第920号共和国法第二节第（b）段第45项关于萨马Calbayog市镇港口的项目并为其他目的法案","en":"An Act to Amend the Item Regarding the Municipal, Port of Calbayog, Samar, Section Two, Paragraph (b), Item Forty-Five of Republic Act Numbered Nine Hundred Twenty, and for Other Purposes","orig":"An Act to Amend the Item Regarding the Municipal, Port of Calbayog, Samar, Section Two, Paragraph (b), Item Forty-Five of Republic Act Numbered Nine Hundred Twenty, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 1158","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1158_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H993-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The item regarding the municipal Port of Calbayog in section two, paragraph (b), item 45 of Republic act Numbered Nine hundred is amended is to read as follows:\n\"45. Calbayog, Samar ₱149,000.00\""}},{"id":"PH-H993-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Item 41, section two, paragraph (a) and items 48, 53 54, 110, 111, 112 and 113 in section two, paragraph (b), are hereby cancelled."}},{"id":"PH-H993-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend the Item Regarding the Municipal, Port of Calbayog, Samar, Section Two, Paragraph (b), Item Forty-Five of Republic Act Numbered Nine Hundred Twenty, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H994"] = {"id":"PH-H994","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1159_1954.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权菲律宾慈善彩票办公室举办一次特别彩票赛，以公共学校局体育项目为受益人的法案","en":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold One Special Sweepstake Race for the Bureau of Public Schools Athletic Program as Beneficiary","orig":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold One Special Sweepstake Race for the Bureau of Public Schools Athletic Program as Beneficiary"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 1159","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1159_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H994-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Philippine Charity Sweepstakes Office shall hold in the year nineteen hundred and fifty-four one special sweepstake horse race the net proceeds of which shall, after deducting the payment of the prizes and expenses as provided in Act Numbered Forty-one hundred and thirty, as amended by Commonwealth Act Numbered Five hundred and forty-six, be turned over to the Director of the Bureau of Public Schools, Manila, for the support of its yearly physical education program including the national interscholastic athletic meet, all expenses therefor to be subject to budgeting and auditing regulations. In said special sweepstake horse race, the prizes for the three winning horses shall be in direct proportion, respectively, to the three main prizes for winning tickets and shall be ten per cent thereof, but in not case shall the total amount of the prizes for winning horses exceed fifty thousand pesos."}},{"id":"PH-H994-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold One Special Sweepstake Race for the Bureau of Public Schools Athletic Program as Beneficiary","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H995"] = {"id":"PH-H995","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1954/ra_1160_1954.html","fetchedAt":"2026-10-06","articleCount":21,"structureMode":"ARTICLE","title":{"zh":"进一步执行经修正的联邦法第 691 号关于自由分配公有农地的规定，废止土地安置与发展公司并设立国家重新安置与复兴管理局替代之，以及为其他目的法案","en":"An Act to Further Implement the Free Distribution of Agricultural Lands of the Public Domain as Provided for in Commonwealth Act Numbered Six Hundred and Ninety-One, as Amended to Abolish the Land Settlement and Development Corporation Created Under Executive Order Numbered Three Hundred and Fifty-Five, Dated October Twenty-Three, Nineteen Hundred and Fifty, and to Create in its Place the National Resettlement and Rehabilitation Administration, and for Other Purposes","orig":"An Act to Further Implement the Free Distribution of Agricultural Lands of the Public Domain as Provided for in Commonwealth Act Numbered Six Hundred and Ninety-One, as Amended to Abolish the Land Settlement and Development Corporation Created Under Executive Order Numbered Three Hundred and Fifty-Five, Dated October Twenty-Three, Nineteen Hundred and Fifty, and to Create in its Place the National Resettlement and Rehabilitation Administration, and for Other Purposes"},"level":"law","status":"active","topics":["company","environment"],"docNumber":"Republic Act No. 1160","issuingBody":"Congress of the Philippines","promulgatedDate":"1954-06-18","completenessNote":"全文，共 21 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1954/ra_1160_1954.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H995-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is hereby declared to be the policy of Congress to help speed up the free distribution of agricultural lands of the public domain to landless tenants and farm workers who are citizens of the Philippines and to encourage migration to sparsely populated regions pursuant to the fundamental policy of the government to promote the level of production, employment and living standards of the people."}},{"id":"PH-H995-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"National Resettlement and Rehabilitation Administration. -In furtherance of the above, policy there is hereby created a corporation to be known as National Resettlement and Rehabilitation Administration hereafter referred to as \"NARRA\" to perform under the supervision and control of the President of the Philippines, through the Office of Economic Coordinator all the duties and functions of the Bureau of Lands as provided in Commonwealth Act Numbered Six hundred and ninety-one as amended, and such other duties as hereinafter specified in this Act. It shall be headed by a General Manager and an Assistant General Manager who shall be appointed as hereinafter provided."}},{"id":"PH-H995-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The NARRA shall have at least three divisions, to wit: (1) Settler Selection and Screening, (2) Transportation and Supplies, and (3) Settlement Assistance and Community Work. The General Manager shall submit at the beginning of each fiscal year, but not later than July thirty-one, a program of activities for the whole fiscal year together with the budget of expenditures to support such a program for the final approval of the President of the Philippines.\nPowers"}},{"id":"PH-H995-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"General powers. -NARRA is hereby authorized to adopt, alter, and use an official seal; to make contracts, to lease or own real and personal property, and to sell or otherwise dispose of the same; to sue and be sued; and to make such regulations as are necessary to execute the functions vested in it by this Act."}},{"id":"PH-H995-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Special powers. -NARRA is authorized:\n(1) To give land, subject to the qualifications, requirements and conditions prescribed by the Public Land Act and under the terms and conditions as may be defined by the Board of Directors, to landless citizens of the Philippines who need, deserve and are capable of tilling the land,\n(2) To facilitate the settlement, acquisition and cultivation of agricultural lands;\n(3) To acquire by purchase such agricultural portions of landed estates as may be directed by the President of the Philippines for the prosecution of the policy stated in section one of this Act.\n(4) To reclaim swamps and marshes, obtain title thereto where feasible, and to support them into agricultural lands for settlement;\n(5) To promote community life in the settlements;\n(6) To borrow money from any credit institution for any of the purposes herein provided;\n(7) To survey, subdivide and set aside lots or areas of such lands for farming, townsites, roads, parks, government centers, and other public and civic improvements, and to dispose of farm lands and townsites lots to persons qualified to the extent of areas authorized under the Constitution and the Public Land Act, subject to such other qualifications and to prices, terms and conditions as may be prescribed by the Board of Directors;\n(8) To secure for the settlers from other government agencies such assistance and facilities as may be necessary to accelerate development, cultivation and electrification of settlements; construction of irrigation systems; institution of credit facilities, enhancement of cottage industries; and establishment of processing plants, warehouses and marketing facilities; and\n(9) To do such other things and to transact all such business directly or indirectly necessary, incidental or conducive to the attainment of the policy enunciated in this Act"}},{"id":"PH-H995-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"In addition to the functions and duties specified and to implement the same properly, the NARRA shall undertake the following activities:\n(1) To select and screen applicants for allocation within the areas set aside for purposes of settlement in the public domain who (a) are bona fide farmers in the highly settled areas, (b) do not own any land with an area of five hectares or more, (c) have not owned any homestead, (d) have not secured any homestead rights from any homesteader, (e) are capable of discharging their responsibilities as settlers, and (f) shall work the land in the settlement areas on the basis of the family-operated, family-type farms: Provided, That in selecting applicants the following order or priority shall be observed: (a) actual bona fide tenants or occupants of the land; (b) surrendered dissidents, who take an oath and show sincere desire, to support the Constitution of the Philippines; (c) graduates of agricultural schools and colleges, (d) trainees who have completed military training; (e) veterans and members of guerrilla organizations; and (f) other applicants possessing the qualifications required herein.\n(2) To assist settlers in transporting themselves, their belongings, work animals and farm equipment, if any, from the communities from which they are migrating to the settlement areas reserved for the purpose, and for subsistence necessary until credit can be provided by the Agricultural Credit and Cooperative Financing Administration (ACCFA) under section thirteen of this Act, or by any other credit institution by loaning to them the full amount required for such purposes. These loans shall be non-interest bearing, a lien upon the land, and shall be amortized over a period of ten years, payable annually beginning with the end of the third year after the date of arrival in the settlement area, subject to the right of the borrower to pay in full at any time prior to the maturity of the loan;\n(3) To assist the said settlers in securing equipment, supplies and materials needed in the settlement areas at the most advantageous prices or terms, and, if requested, to assist the cooperative associations of the new settlers in securing the most advantageous prices or terms on farm implements and supplies needed by the cooperative associations and their members;\n(4) To help provide housing and other accommodations for the new settlers in the settlement areas upon arrival by locating them in properly surveyed and subdivided lots reserved for the purpose, to help organize community activities that the new settlers require upon arrival in the new settlement, and to cooperate with the agricultural extension service, the Bureau of Health, the Bureau of Public Schools and other pertinent agencies of the Government, in providing the services for the proper establishment of community facilities as well as the organization of collective efforts essential to development in the new settlement areas.\n(5) To submit its annual report and balance sheets to the President and the Congress of the Philippines, as provided in sections five hundred and seventy-four to five hundred and seventy-seven of the Administrative Code;\n(6) To appoint and fix the number and salaries, upon recommendation of the Office of Economic Coordination and with the approval of the President of the Philippines and subject to Civil Service Law and Rules and the salary law, of such subordinate personnel as may be necessary for the proper discharge of its duties and functions and upon recommendation of the Office of Economic Coordination and with the approval of the President, suspend, remove or otherwise discipline, any of its subordinate employees, and\n(7) To perform such other related duties as may be assigned to it by the President of the Philippines from time to time."}},{"id":"PH-H995-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Board of Directors—Its Compositions, tenure of office and meetings. -The powers and functions of NARRA shall be exercised by a Board of Directors to be composed of a Chairman and five members. They shall be appointed by the President of the Philippines with the consent of the Commission on Appointments for a term of three years. Any person chosen to fill a vacancy shall serve only for the unexpired term of the member whom he succeeds.\nThe Board shall hold regular meetings and such number of special meetings as may be called by the Chairman or any three members from time to time; Provided, However, That the total number of meetings of the Board shall not be more than four a month. The Chairman and the members shall each receive a per diem of twenty-five pesos for every meeting actually intended."}},{"id":"PH-H995-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Powers and duties of the Board of Directors. -The Board of Directors shall have the following powers and duties:\n(1) To prescribe, amend and repeal by laws, rules and regulations governing the manner in which the general business of NARRA may be exercised, including provisions regarding subdivision of lands into small farm lots, distribution thereof, initial aid to settlers and manner of payment of such lots, and provisions for the formation of such committee or committees as the General Manager may deem necessary to facilitate the business of the NARRA, and to expedite the disposition of, and the issuance of titles, over said farm lots of contemplated in section five;\n(2) To appoint and fix the term of office of the General Manager, and Assistant General Manager, whose compensation shall be twelve thousand pesos per annum for the General Manager, and nine thousand pesos per annum for the Assistant General Manager, subject to the recommendation of the Office of Economic Coordination and the approval of the President of the Philippines, and to appoint and fix the compensation of a Secretary of the Board and such other officers of the Corporation as may be needed. The Board, by majority vote of all the members, may for cause, upon recommendation of the Office of Economic Coordination and with the approval of the President of the Philippines, suspend and/or remove the General Manager and/or the Assistant General Manager; and(3) To approve the annual budget and such supplemental budgets of NARRA which may be submitted to it by the General Manager from time to time."}},{"id":"PH-H995-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"NARRA shall be the custodian and administrator of public lands reserved or may hereafter be reserved by the President of the Philippines for settlement, all lands actually reserved for the Land Settlement and Development Corporation (LASEDECO), and the agricultural lands surveyed and subdivided under Commonwealth Act Numbered Six hundred ninety-one."}},{"id":"PH-H995-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Land Settlement and Development Corporation created under Executive Order Numbered Three hundred fifty-five, dated October twenty-three, nineteen hundred and fifty, known for short as LASEDESCO, is hereby abolished, and all its obligations under said Executive Order, except its commercial accounts which are to be paid as hereinafter provided, are hereby transferred to the Treasury of the Philippines to be amortized over a period of fifteen years subject to the availability of funds of the Government.\nAll assets of the LASEDECO, including farm machinery and equipment, shall be turned over to a Board of Liquidators and shall be sold at public auction, the proceeds thereof to be used in paying off its accounts with commercial firms and the net proceeds to be transferred to the Agricultural Credit and Cooperative Financing Administration (ACCFA) for loan to settlers or cooperative organizations of settlers as provided for under this Act: Provided, However, That such buildings, equipment, and machinery as may be needed the settlers’ cooperatives either in the area where such property is located or in areas being settled under the provisions of this Act may be transferred to the said cooperatives at an appraised value fixed by the Board of Liquidators."}},{"id":"PH-H995-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"To carry out of the purposes of this Act, there is hereby appropriated for the \"Revolving Fund of the Colonists\", as provided for in Commonwealth Act Numbered Six hundred and ninety-one, the sum of five million pesos for the fiscal year 1954-1955 out of any funds in the National Treasury not otherwise appropriated, to be spent by the NARRA upon recommendation of the Office of Economic Coordination and under the supervision and authority of the President of the Philippines for the activities prescribed herein. A sum of not less than eight million pesos for every fiscal year thereafter, for a period of ten years, shall be included in the General Appropriations Acts for the subsequent fiscal years for the said \"Revolving Fund of the Colonists\" to carry out the purposes of this Act."}},{"id":"PH-H995-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"All public agricultural lands referred to in section fourteen of Executive Order Numbered Three hundred and fifty-five, dated October Twenty-three, nineteen hundred and fifty, are hereby transferred to the jurisdiction of the NARRA to be disposed of in accordance with the provisions of this Act: Provided, That the settlement of the agricultural lands so transferred under this section by voluntary settlers who do not receive any direct assistance under the provisions of this Act or by duly qualified homestead applicants shall not be precluded nor obstructed."}},{"id":"PH-H995-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"In addition to the financial aid that may be given to settlers from the \"Revolving Fund of the Colonists\", the Agricultural Credit and Cooperative Financing Administration (ACCFA) created under Republic Act Numbered Eight Hundred and twenty-one is hereby authorized to give loans or financial assistance to the settlers or settlers cooperatives to help establish themselves as independent farmers following their arrival in the settlement areas: Provided, However , That it may require any borrower to become a bona fide member of a cooperative association in the settlement areas as a condition for giving such financial aid or loan. Such loans shall be subject to the conditions specified in section six, subsection two, of this Act, with the modification that the lien shall be on the borrower’s produce and that the amortization period shall begin one year after the date of the loan.\nTransitory and Special Provisions"}},{"id":"PH-H995-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The officials, employees and laborers of the LASEDECO who may be separated from the service by virtue hereof and who are entitled to retire under Republic Act Numbered Six hundred sixty shall be so retired upon the payment of the obligations of the LASEDECO to the Government Service Insurance System subsisting under said account on the date of the approval hereof. Those who may not be retired shall be entitled to thirty days’ separation pay, the money value of earned vacation and sick leaves, and gratuity which shall be paid in one lump sum equivalent to one month’s salary for every year of satisfactory service rendered in any branch of the government and government agencies and the instrumentalities on the basis of the highest salary received by them; Provided, That any of said officials, employees or laborers who has rendered less than one year of service shall be paid in one lump sum a gratuity equivalent to one half of one months’ salary: And Provided, further, That in case of subsequent reinstatement in the Government service or in any Government-owned or controlled corporation of any such official, employee or laborer who has been paid gratuity hereunder, he shall refund to the National Government the value of the gratuity which he would not have as yet received if it had been payable in monthly installments."}},{"id":"PH-H995-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Subject to the provisions of section ten hereof, the President of the Philippines shall provide by executive order for the liquidation of the assets and liabilities of LASEDECO and is hereby authorized to transfer to NARRA such properties, equipment, assets and rights of LASEDECO as may be needed by the former in carrying out the purposes and objectives of this Act."}},{"id":"PH-H995-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Any provision of law to the contrary notwithstanding, all surveyed portions of the public agricultural lands heretofore transferred or reserved for the administration of NARRA under this Act and of those which may hereafter be transferred by the President of the Philippines to NARRA for the purposes of this Act, shall be ceded to NARRA, and the President of the Philippines shall from time to time cause the issuance of patents or other deeds transferring title to such lands to NARRA in accordance with the provisions of the Public Land Act and such rules and regulations as may be promulgated to facilitate the transfer of title to NARRA.\nPenal Provisions"}},{"id":"PH-H995-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"No officer or employee of NARRA shall be permitted in any manner to acquire, directly or indirectly, any land within the land settlement projects of NARRA. Any such officer or employee who violates the provisions of this section shall immediately be removed by competent authority and said officer or employee shall be punished by imprisonment for not less than one year nor exceeding five years and by a fine of not less than one thousand nor more than five thousand pesos. Should a dummy be used to violate the provisions of this section, the same penalty shall be applied to the dummy."}},{"id":"PH-H995-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"No official or employee of the Corporation shall directly or indirectly be financially interested in any contract with the corporation or in any special privilege granted by said corporation during his term of office. Any violation of this prohibition shall be punished by dismissal from office and by a fine of not more than five thousand pesos and imprisonment of not more than five years.\nMiscellaneous Provisions"}},{"id":"PH-H995-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"If any provision of this Act is declared unconstitutional, or the applicability thereof to any person, circumstance, or transaction is held invalid, the validity of the remainder of the Act and the applicability of such provision to other persons, circumstances, and transactions shall not be affected thereby."}},{"id":"PH-H995-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"All Act, parts of Act, and any special charters, or parts thereof, inconsistent herewith are hereby repealed."}},{"id":"PH-H995-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1954."}}],"pack":"ph-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Implement the Free Distribution of Agricultural Lands of the Public Domain as Provided for in Commonwealth Act Numbered Six Hundred and Ninety-One, as Amended to Abolish the Land Settlement and Development Corporation Created Under Executive Order Numbered Three Hundred and Fifty-Five, Dated October Twenty-Three, Nineteen Hundred and Fifty, and to Create in its Place the National Resettlement and Rehabilitation Administration, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
